AutoForm.hooks({
  gamesessionUpdate: {
    before: {
      update: function(doc) {
        form = Session.get('newGamesession');

        // Format the date time
        var meetingDate = moment(doc.$set.meetingDate, "DD/MM/YYYY HH:mm");
        doc.$set.meetingDate = moment(meetingDate).unix();

        // Choose a cover
        var newCover = (form.category === 'videogame')? Meteor.absoluteUrl()+'/images/cover_video.svg' : Meteor.absoluteUrl()+'/images/cover_board.svg';
        if(form.games && form.games.length > 0) newCover = form.games[0].cover;
        doc.$set.cover = newCover;

        // Generate a title
        var newTitle = { what: TAPi18n.__('gamesessionCreateGames'), where: '', when: ''};

        // Where
        if(doc.$set.meetingType) {
          if(doc.$set.meetingType === 'irl') {
            if(doc.$set['meetingPlace.address.city']) {
              newTitle.where = TAPi18n.__('helper.inCity', doc.$set['meetingPlace.address.city']);
              if(doc.$set['meetingPlace.address.zipCode']) {
                newTitle.where += ' ('+doc.$set['meetingPlace.address.zipCode']+')';
              }
            } else if(doc.$set['meetingPlace.address.zipCode']) {
              newTitle.where = TAPi18n.__('helper.inZipCode', doc.$set['meetingPlace.address.zipCode']);
            }
          } else if (doc.$set.meetingType === 'online') {
            if(doc.$set['meetingPlace.service.title'] != 'other') {
              var key = TAPi18n.__('schemas.gamesession.meetingPlace.service.title.options.'+doc.$set['meetingPlace.service.title']);
              newTitle.where = TAPi18n.__('helper.onPlatform', key);
            }
          }
        }
        // What
        if(form.category === 'boardgame') {
          newTitle.what = TAPi18n.__('gamesessionCreateBoardGames');
        } else if(form.category === 'videogame') {
          newTitle.what = TAPi18n.__('gamesessionCreateVideoGames');
        }
        if(form.games.length === 1) {
          newTitle.what = form.games[0].title;
        } else {
          newTitle.when = splitDay(moment(doc.$set.meetingDate, 'X').hour());
        }
        doc.$set.title = newTitle.when + ' ' + newTitle.what + ' ' + newTitle.where;

        // Add games
        doc.$set.games = form.games.map(function(item,index){
          if(!item.gameId) item.gameId = item._id;
          return item;
        });

        delete doc.$set['games.$.title'];
        delete doc.$unset['games.$'];

        return doc;
      }
    },
    onSuccess: function(t, result) {
      FlowRouter.go('gamesessionList');
    },
    onError: function(formType, error) {
      console.log(error);
    }
  }
});

/**
 * LEETCODE 151: Reverse Words in String
 *
 * https://leetcode.com/problems/reverse-words-in-a-string/
 *
 * Given an input string, reverse the string word by word. A word is
 * defined as a sequence of non-space characters.
 *
 * The input string does not contain leading or trailing spaces and the
 * words are always separated by a single space. For example, Given s =
 * "the sky is blue", return "blue is sky the".
 */

// SOLUTION #1: WITH STACK
const reverseWords = input => {
  // what we return
  let returnValue = "";

  // parse input, throw words into a Stack
  const stack = [];
  const tokens = input.split(" ");
  tokens.forEach(token => {
    if (token.length > 0) stack.push(token); // trim spaces before & after?
  });

  // iterate thru stack, build output
  stack.reverse().forEach(word => {
    returnValue += word + " ";
  });
  returnValue = returnValue.trim();

  // finally return
  return returnValue;
};

// SOLUTION #2: IN PLACE
const noStackReverseWords = input => {
  // what we return
  let returnValue = "";

  // reverse input
  input = input
    .split("")
    .reverse()
    .join("");
  console.log(input);

  returnValue = input
    .split(" ")
    .map(word => {
      return word
        .split("")
        .reverse()
        .join("");
    })
    .join(" ");

  // finally return
  return returnValue;
};

//// TEST CASES ////

// 1
let input = "the sky is blue";
let output = noStackReverseWords(input);
console.log("in:  <" + input + ">\nout: <" + output + ">");

// 2
console.log("====");
input = "  welcome to Florida!";
output = noStackReverseWords(input);
console.log("in:  <" + input + ">\nout: <" + output + ">");

