				(a.protocol === window.location.protocol &&
					a.hostname === window.location.hostname &&
					a.port === (window.location.port ||
						(window.location.protocol === "https:" ? "443" : "80")))) {
			result = true;
		}
		return result;
	},
	simplifyFileURL: function(inUrl) {
		var a = document.createElement("a"), result = false;
		a.href = inUrl;
		// protocol is ":" for relative URLs
		if (a.protocol === "file:" ||
			a.protocol === ":" && window.location.protocol === "file:") {
			// leave off search and hash parts of the URL
			return a.protocol + '//' + a.host + a.pathname;
		} else if (a.protocol === ":" && window.location.protocol === "x-wmapp0:") {
			// explicitly return absolute URL for Windows Phone 8, as an absolute path is required for local files
			return window.location.protocol + "//" + window.location.pathname.split('/')[0] + "/" + a.host + a.pathname;
		} else {
			return inUrl;
		}
	},
	getXMLHttpRequest: function(inParams) {
		try {
			// only use XDomainRequest when it exists, no extra headers were set, and the
			// target URL maps to a domain other than the document origin.
			if (enyo.platform.ie < 10 && window.XDomainRequest && !inParams.headers &&
				!this.inOrigin(inParams.url) && !/^file:\/\//.test(window.location.href)) {
				return new XDomainRequest();
			}
		} catch(e) {}
		try {
			return new XMLHttpRequest();
		} catch(e) {}
		return null;
	}
};

import Outlet from '../../../../src/classes/outlet';

import {
    mountSpies,
    cMountSpies,
} from '../sinon-spies';

import { SinonSpyRootApp } from './base-mounts';

import {
    RootRootRoute,
    RootNewsRoute,
    RootAllConditionalRoute,
    RootNewsConditionalRoute,
    RootIdConditionalRouteOne,
    RootIdConditionalRouteTwo,
    RootConditionalRoute,
} from './root-routes';

import TodoApp from './todo-app/';
import UserApp from './user-app/';

// need to make sure to mount each mount class and
// each conditional mount class exactly once,
// to ensure spy call counts are unique and correct
class MyRootApp extends SinonSpyRootApp {
    createOutlets(outlets) {
        // mounts
        outlets.RootRootRoute = new Outlet(document.createElement('div'));
        outlets.RootNewsRoute = new Outlet(document.createElement('div'));
        outlets.TodoApp = new Outlet(document.createElement('div'));
        outlets.UserApp = new Outlet(document.createElement('div'));
        // conditional mounts
        outlets.RootAllConditionalRoute = new Outlet(document.createElement('div'));
        outlets.RootNewsConditionalRoute = new Outlet(document.createElement('div'));
        outlets.RootIdConditionalRouteOne = new Outlet(document.createElement('div'));
        outlets.RootIdConditionalRouteTwo = new Outlet(document.createElement('div'));
        outlets.RootConditionalRoute = new Outlet(document.createElement('div'));
        return outlets;
    }
    mount() {
        return {
            '':
                RootRootRoute
                    .addresses('rootRoot')
                    .outlets('RootRootRoute')
                    .setup(() => mountSpies),
            'news/{news=\\w+}':
                RootNewsRoute
                    .outlets('RootNewsRoute')
                    .setup(() => mountSpies),
            'todos/{id=\\d+}':
                TodoApp
                    .addresses('todoApp')
                    .outlets('TodoApp')
                    .setup(() => mountSpies),
            'user/{id=\\d+}':
                UserApp
                    .addresses('userApp')
                    .outlets('UserApp')
                    .setup(() => mountSpies),
        };
    }
    mountConditionals() {
        return {
            '*':
                RootAllConditionalRoute
                    .outlets('RootAllConditionalRoute')
                    .setup(() => cMountSpies),
            '!todoApp,userApp,rootRoot':
                RootNewsConditionalRoute
                    .outlets('RootNewsConditionalRoute')
                    .setup(() => cMountSpies),
            '+userApp': [
                RootIdConditionalRouteOne
                    .outlets('RootIdConditionalRouteOne')
                    .setup(() => cMountSpies),
                RootIdConditionalRouteTwo
                    .outlets('RootIdConditionalRouteTwo')
                    .setup(() => cMountSpies),
            ],
            '+rootRoot':
                RootConditionalRoute
                    .outlets('RootConditionalRoute')
                    .setup(() => cMountSpies),
        };
    }
}

export default MyRootApp.setup(() => mountSpies);

import Client from './Client';
import sinon from 'sinon';
import { expect } from './tests/chai';

describe('Client', () => {
  it('makes a GET request', () => {
    const superagent = {
      get: sinon.stub(),
    };
    superagent
      .get.withArgs('http://example.com/custom-path')
      .returns(Promise.resolve({
        body: {
          property: 'value',
        },
        status: 200,
      }));

    const client = new Client(superagent);
    client.setHost('http://example.com');

    return client.get('/custom-path')
      .then(response => {
        expect(response.body).to.matchPattern(
          `
            {
              "property": "value",
            }
          `
        );
        expect(response.status).to.be.equal(200);
      });
  });

  it('makes a POST request', () => {
    const body = {
      property: 'value',
      other: 'value',
    };
    const superagent = {
      post: sinon.stub(),
    };
    const poster = {
      send: sinon.stub(),
    };

    superagent.post.withArgs('http://example.com/custom-path')
      .returns(poster);

    poster.send.withArgs(body)
      .returns(Promise.resolve({
        body: {
          property: 'value',
        },
        status: 201,
      }));

    const client = new Client(superagent);
    client.setHost('http://example.com');

    return client.post('/custom-path', body)
      .then(response => {
        expect(response.body).to.matchPattern(
          `
            {
              "property": "value",
            }
          `
        );
        expect(response.status).to.be.equal(201);
      });
  });

  it('sets headers', () => {
    const superagent = {
      get: sinon.stub(),
    };
    const request = {
      set: sinon.spy(),
      then: () => Promise.resolve(),
    };

    superagent
      .get.withArgs('http://example.com/path')
      .returns(request);

    const client = new Client(superagent);
    client.setHost('http://example.com');
    client.setHeader('Accept', 'application/json');

    return client.get('/path')
      .then(response => {
        expect(request.set.withArgs('Accept', 'application/json')).to.have.been.calledOnce;
      });
  });
});

