class FindProject extends PureComponent {
  state ={
    addVisible:false,
    updateVisible:false,
    viewVisible:false,
    updata:{},
    view:{},
  }

  componentDidMount() {
    const { dispatch } = this.props;
    dispatch({
      type:'CM/fetch',
      payload:{
        reqData:{
          pageIndex:0,
          pageSize:10
        }
      }
    })
  }

  //新建模态框
  handleModalVisible = (bool)=>{
    this.setState({
      addVisible:bool
    })
  }

 //修改模态框
  updateChange = (e,record)=>{
    e.preventDefault();
    this.setState({
      updateVisible:true,
      updata:record
    })
  }
  updateChangeVisible = (bool)=>{
    this.setState({
      updateVisible:bool
    })
  }



//查看模态框
  viewChange = (e,record)=>{
    e.preventDefault();
    this.setState({
      viewVisible:true,
      view:record
    })
  }
  viewHandleVisible = (bool) =>{
    this.setState({
      viewVisible:bool
    })
  }



  //删除
  handleDelete = (record)=>{
    const { id } = record;
    const { dispatch } = this.props;
    dispatch({
      type:'CM/delete',
      payload:{
        reqData:{
          id
        }
      },
      callback:(res)=>{
        if(res){
          message.success("删除成功",1,()=>{
            dispatch({
              type:'CM/fetch',
              payload:{
                reqData:{
                  pageIndex:0,
                  pageSize:10
                }
              }
            })
          })
        }
      }
    })
  }


  renderForm() {
    const {
      form: { getFieldDecorator },
    } = this.props;
    return (
      <Form onSubmit={this.findList} layout="inline">
        <Row gutter={{ md: 8, lg: 24, xl: 48 }}>
          <Col md={8} sm={16}>
            <FormItem label='客户名称'>
              {getFieldDecorator('projectname')(<Input placeholder='项目名称' />)}
