export default function createUrl(baseUrl, params) {
    const paramsStr = qs.stringify(params || {});
    if (!paramsStr) {
        return baseUrl;
    }

    let subStr = '';
    // 没有问号
    if (baseUrl.lastIndexOf('?') === -1) {
        subStr = '?';
    } else {
        // 最后一个字符
