Uit.cleanView = function (view) {
    if (!_.isUndefined(view)) {
        view.onClose = view.onClose || function () {
            };

        view.onClose();
        if (view.rivets) {
            view.rivets.unbind();
        }
        view.unbind(); // Unbind all local event bindings

        if (view.model) {
            view.model.unbind('change', view.render, view); // Unbind reference to the model
