const BudgetType = require('./BudgetType');

class SplitBudget extends BudgetType {
  get priority() {
    return this.config.priority || 200;
  }

  run(runningBalance) {
    if (runningBalance <= 0) {
      this.addDebugMessage('We have no running balance to use!');

      return this.setValue(0, (this.config.failOnEmpty === false) ? 'warning' : 'failed');
    }

    return this.setValue(runningBalance, 'success');
  }
}

module.exports = SplitBudget;

import React from 'react'
import {connect} from 'react-redux'

import {fetchProducts} from '../store/allProducts'
import ProductView from './ProductView'

export class AllProducts extends React.Component {
  constructor() {
    super()
    this.state = {sort: 'random', filter: 'all'}
    this.handleChange = this.handleChange.bind(this)
    this.handleFilter = this.handleFilter.bind(this)
  }
  componentDidMount() {
    if (this.props.loadProducts) this.props.loadProducts()
  }
  handleChange(event) {
    this.setState({sort: event.target.value})
  }
  handleFilter(event) {
    this.setState({filter: event.target.value})
  }
  render() {
    let filteredProducts = this.props.products

    //Logic for filtering and sorting below

    if (this.state.filter === 'rats') {
      filteredProducts = filteredProducts.filter(p => {
        return p.sex
      })
    }

    if (this.state.filter === 'accessories') {
      filteredProducts = filteredProducts.filter(p => {
        return !p.sex
      })
    }

    if (this.state.sort === 'highLow') {
      filteredProducts.sort((a, b) => {
        return a.price < b.price ? 1 : -1
      })
    }

    if (this.state.sort === 'lowHigh') {
      filteredProducts.sort((a, b) => {
        return a.price > b.price ? 1 : -1
      })
    }

    return (
      <div className="allProducts">
        <div id="productViews">
          {filteredProducts
            ? filteredProducts.map(product => {
                return (
                  <ProductView
                    product={product}
                    key={product.id}
                    isAdmin={this.props.user.isAdmin}
                  />
                )
              })
            : ''}
        </div>
        <div id="sortFilter">
          <div>
            <h3>Sort:</h3>
            <select value={this.state.sort} onChange={this.handleChange}>
              <option value="random">Any order</option>
              <option value="highLow">Price (high-low)</option>
              <option value="lowHigh">Price (low-high)</option>
            </select>
          </div>

          <div>
            <h3>Filter:</h3>
            <select value={this.state.filter} onChange={this.handleFilter}>
              <option value="all">All products</option>
              <option value="rats">Rats for adoption</option>
              <option value="accessories">Rat accessories</option>
            </select>
          </div>
        </div>
      </div>
    )
  }
}

const mapState = state => {
  return {
    products: state.products,
    user: state.user
  }
}

const mapDispatch = dispatch => {
  return {
    loadProducts: () => {
      dispatch(fetchProducts())
    }
  }
}

export default connect(mapState, mapDispatch)(AllProducts)

