var schema = buildSchema(`
type Query{
  restaurant(id: Int): Restaurant
  restaurants: [Restaurant]
},
type Restaurant {
  id: Int
  name: String
  description: String
  dishes:[Dish]
}
type Dish{
  name: String
  price: Int
}
input RestaurantInput{
  id: Int
  name: String
  description: String
}
type DeleteResponse{
  ok: Boolean!
}
type Mutation{
  setrestaurant(input: RestaurantInput): Restaurant
  deleterestaurant(id: Int!): DeleteResponse
  editrestaurant(id: Int!, name: String!): Restaurant
}
`);
// The root provides a resolver function for each API endpoint

var root = {
  restaurant: ({id}) => restaurants.find(restaurant => restaurant.id === id),
  restaurants: () => restaurants,
  setrestaurant: ({ input }) => {
    restaurants.push({name: input.name, description: input.description, id:input.id})
    return input
  },
  deleterestaurant: ({ id }) => {
    const ok = Boolean(restaurants.find(restaurant => restaurant.id === id))
    let delrest = restaurants.find(restaurant => restaurant.id === id);
    restaurants = restaurants.filter(restaurant => restaurant.id !== id)
    console.log(JSON.stringify(delrest))
    return {ok}
  },
  editrestaurant: ({ id, ...restaurant }) => {
    let targetIndex = restaurants.findIndex(restaurant =>restaurant.id === id)
    if(!restaurants[targetIndex]){
      throw new Error("restaurant doesn't exist")
    }
    restaurants[targetIndex] = {
      ...restaurants[targetIndex], ...restaurant
    }
    return restaurants[targetIndex]
  },
};
var app = express();
app.use(
