import {
  calculateEntryPointScriptUrl,
  calculateExtensionScriptUrl,
  parseExtensionUrl,
} from '../../src/service/extension-location';
import {initLogConstructor, resetLogConstructorForTesting} from '../../src/log';

describes.sandboxed('Extension Location', {}, () => {
  describe('get correct script source', () => {
    beforeEach(() => {
      // These functions must not rely on log for cases in SW.
      resetLogConstructorForTesting();
    });

    afterEach(() => {
      initLogConstructor();
    });

    it('with local mode', () => {
      window.__AMP_MODE = {rtvVersion: '123'};
      const script = calculateExtensionScriptUrl(
        {
          pathname: 'examples/ads.amp.html',
          host: 'localhost:8000',
          protocol: 'http:',
        },
        'amp-ad',
        /*opt_extensionVersion*/ undefined,
        true
      );
      expect(script).to.equal(
        'http://localhost:8000/dist/rtv/123/v0/amp-ad-0.1.js'
      );
    });

    it('with remote mode', () => {
      window.__AMP_MODE = {rtvVersion: '123'};
      const script = calculateExtensionScriptUrl(
        {
          pathname: 'examples/ads.amp.html',
          host: 'localhost:8000',
          protocol: 'http:',
        },
        'amp-ad',
        /*opt_extensionVersion*/ undefined,
        false
      );
      expect(script).to.equal(
        'https://cdn.ampproject.org/rtv/123/v0/amp-ad-0.1.js'
      );
    });

    it('should allow no versions', () => {
      window.__AMP_MODE = {rtvVersion: '123'};
      const script = calculateExtensionScriptUrl(
        {
          pathname: 'examples/ads.amp.html',
          host: 'localhost:8000',
          protocol: 'http:',
        },
        'no-version',
        /* version is empty but defined */ '',
        true
      );
      expect(script).to.equal(
        'http://localhost:8000/dist/rtv/123/v0/no-version.js'
      );
    });

    it('should handles single pass experiment', () => {
      window.__AMP_MODE = {rtvVersion: '123', singlePassType: 'sp'};
      const script = calculateExtensionScriptUrl(
        {
          pathname: 'examples/ads.amp.html',
          host: 'localhost:8000',
          protocol: 'http:',
        },
        'no-version',
        /* version is empty but defined */ '',
        true
      );
      expect(script).to.equal(
        'http://localhost:8000/dist/rtv/123/sp/v0/no-version.js'
      );
    });
  });

  describe('get correct entry point source', () => {
    beforeEach(() => {
      // These functions must not rely on log for cases in SW.
      resetLogConstructorForTesting();
    });

    afterEach(() => {
      initLogConstructor();
    });

    it('with local mode', () => {
      const script = calculateEntryPointScriptUrl(
        {
          pathname: 'examples/ads.amp.html',
          host: 'localhost:8000',
          protocol: 'http:',
        },
        'sw',
        true
      );
      expect(script).to.equal('http://localhost:8000/dist/sw.js');
    });

    it('with remote mode', () => {
      window.__AMP_MODE = {rtvVersion: '123'};
      const script = calculateEntryPointScriptUrl(
        {
          pathname: 'examples/ads.amp.html',
          host: 'localhost:8000',
          protocol: 'http:',
        },
        'sw',
        /* isLocalDev */ false
      );
      expect(script).to.equal('https://cdn.ampproject.org/sw.js');
    });

    it('with remote mode & rtv', () => {
      window.__AMP_MODE = {rtvVersion: '123'};
      const script = calculateEntryPointScriptUrl(
        {
          pathname: 'examples/ads.amp.html',
          host: 'localhost:8000',
          protocol: 'http:',
        },
        'ww',
        /* isLocalDev */ false,
        /* opt_rtv */ true
      );
      expect(script).to.equal('https://cdn.ampproject.org/rtv/123/ww.js');
    });

    it('should handle single pass experiment', () => {
      window.__AMP_MODE = {rtvVersion: '123', singlePassType: 'sp'};
      const script = calculateEntryPointScriptUrl(
        {
          pathname: 'examples/ads.amp.html',
          host: 'localhost:8000',
          protocol: 'http:',
        },
        'ww',
        /* isLocalDev */ false,
        /* opt_rtv */ true
      );
      expect(script).to.equal('https://cdn.ampproject.org/rtv/123/sp/ww.js');
    });
  });

  describe('get correct URL parts', () => {
    it('unversioned urls', () => {
      const urlParts = parseExtensionUrl(
        'https://cdn.ampproject.org/v0/amp-ad-1.0.js'
      );
      expect(urlParts.extensionId).to.equal('amp-ad');
      expect(urlParts.extensionVersion).to.equal('1.0');
    });

    it('versioned urls', () => {
      const urlParts = parseExtensionUrl(
        'https://cdn.ampproject.org/rtv/123/v0/amp-ad-0.1.js'
      );
      expect(urlParts.extensionId).to.equal('amp-ad');
      expect(urlParts.extensionVersion).to.equal('0.1');
    });
  });
});

import React, { useState } from 'react';
import PropTypes from 'prop-types';
import TipImage from '@assets/img/gold-tip.svg';

export default function TipsWidget({ tips }) {
  const [active, setActive] = useState(0);

  return (
    <div>
      <div className='pl-2 md:pl-0 mb-8 md:mb-10'>
        <h2 className='text-black-900 text-xl font-semibold font-head'>Tips</h2>
      </div>
      {/** tips container */}
      <div className='bg-gray-500 px-6 py-6 rounded-2xl'>
        <div className='flex items-center justify-between mb-5 px-2'>
          {tips.map(({ title }, index) => (
            <h3
              key={index + title}
              className={`font-bold text-lg text-black-900 ${
                index === active ? 'block' : 'hidden'
              }`}>
              {title}
            </h3>
          ))}
          <img src={TipImage} alt='tips' />
        </div>
        <div>
          {tips.map(({ title, description }, index) => (
            <p
              key={index + title}
              className={`text-sm text-black-900 ${
                index === active ? 'block' : 'hidden'
              }`}>
              {description}
            </p>
          ))}
        </div>
      </div>
      {/** tips pagination */}
      <div className='px-6 mt-8 flex items-center'>
        {tips.map(({ title }, index) => (
          <button
            type='button'
            onClick={() => setActive(index)}
            className={`w-10 h-1 mr-3 rounded-lg ${
              index === active ? 'bg-primary-900' : 'bg-gray-600'
            }`}
          />
        ))}

        <button
          type='button'
          onClick={() => {
            if (active >= tips.length - 1) {
              setActive(0);
            } else {
              setActive(active + 1);
            }
          }}
          className='text-xs text-black-900 font-semibold font-head ml-4'>
          Next
        </button>
      </div>
    </div>
  );
}

TipsWidget.propTypes = {
  tips: PropTypes.arrayOf(PropTypes.object).isRequired,
};

