/**
 * 判断是否为JSON对象
 * @param json JSON对象
 */
var isJSON = function(json) {
  return (typeof json == 'object') && Object.prototype.toString.call(json).toLowerCase() == "[object object]" && !json.length;
};

/**
 * 判断是否为空JSON
 * @param json JSON对象
 */
var isEmptyJSON = function(json) {
  if (isJSON(json)) {
    for ( var name in json) {
      return false;
    }
    return true;
  }
  return false;
};

/**
