    return async function (dispatch) {
        const result = await api.appLoginRequest({
            ...params,
            platform: Platform.OS
        })
        if (result.status === 200) {
            await dispatch(updateUserBasicInfo(result.user_id, result.access_token))
        }
        return result
    }
}

