function createRow(data,i){
	var row      = $('<tr></tr>');
	var cell     = $('<td></td>');
	cell.append(i+1);
	row.append(cell);
	var cell     = $('<td></td>');

	for (var j = 0; j < 6; j++) {
		cell.append(data[j][0]);
		if (!data[j][1]) {
			cell.css("background-color","red");
		}
			row.append(cell);
			var cell     = $('<td></td>');
	}
	return row;
}

