db = require("../dbConfig.js");
const dbTeamMembers = require("./teamMembersDb");
const table = "slackAuth";

module.exports = {
  get: function() {
    return db(table);
  },
  getID: function(id) {
    return db(table).where("id", id);
  },
  getByMemberId: function(member_id) {
    return db(table).where("member_id", member_id);
  },
  getBySlackUserId: function(user_id) {
    return db(table).where("user_id", user_id);
  },
  getBySlackTeamId: function(team_id) {
    return db(table)
      .where({ team_id: team_id })
      .then(data => {
        for (let y = 0; y < data.length; y++) {
          return db("teamMembers").where({
            id: data[y].member_id,
            type: "manager"
          });
        }
      });
  },
  getBySlackTeamIdSTD: function(team_id) {
    return db(table).where({ team_id: team_id });
  },
  getByBotId: function(bot_user_id) {
    return db(table).where("bot_user_id", bot_user_id);
  },
  insert: function(post) {
    return db(table)
      .insert(post)
      .then(ids => ({ id: ids[0] }));
  },
  update: function(id, post) {
    return db(table)
      .where("id", id)
      .update(post);
  },
  remove: function(id) {
    return db(table)
      .where("id", id)
      .del();
  }
};

class Layer
{
    constructor(name, colorNumber, lineTypeName)
    {
        this.name = name;
        this.colorNumber = colorNumber;
        this.lineTypeName = lineTypeName;
        this.shapes = [];
    }

    toDxfString()
    {
        let s = '0\nLAYER\n';
        s += '70\n64\n';
        s += `2\n${this.name}\n`;
        s += `62\n${this.colorNumber}\n`;
        s += `6\n${this.lineTypeName}\n`;
        return s;        
    }

    addShape(shape)
    {
        this.shapes.push(shape);
        shape.layer = this;
    }

    getShapes()
    {
        return this.shapes;
    }

    shapesToDxf()
    {
        let s = '';
        for (let i = 0; i < this.shapes.length; ++i)
        {
            s += this.shapes[i].toDxfString();
        } 


        return s;
    }
}

module.exports = Layer;

