              ++found;
            } catch (e) {
            }
          });
          if (found !== 1) // slightly misleading error, but adequate.
            expect(m).to.deep.equal(mapping);
        } else {
          expect(m).to.deep.equal(mapping);
        }
      }
    });
  }

