class AddFolder extends React.PureComponent {
    constructor(props) {
        super(props);

        this.state = {
            isInputVisible: false,
        };

        this.toggleInput = this.toggleInput.bind(this);
    }

    toggleInput(isInputVisible) {
        this.setState({ isInputVisible });
