    render() {
        return (
            <animated.li>
                <RenameFolder
                    resetOnHide
                    motion="verticalSlide"
                    isInputVisible={this.state.isInputVisible}
                    toggleInput={this.toggleInput}
                    renderElement={style => (
                        <FolderItemLabel
                            style={style}
                            label="add folder"
                            icon="plus"
                            onClick={() => { this.toggleInput(true); }}
                        />
                    )}
                    onEnter={(value) => { this.props.addFolderCallback(value); }}
                />
            </animated.li>
        );
    }
}

AddFolder.propTypes = {
    addFolderCallback: PropTypes.func.isRequired,
};

export { AddFolder };

import beautify from 'js-beautify';

const beautifyOptions = {
  indent_size: 2,
  wrap_line_length: 80,
  wrap_attributes: 'force-expand-multiline',
};

function html(html) {
  return beautify.html(html, beautifyOptions);
}

function js(js) {
  return beautify.js(js, beautifyOptions);
}

function format(mode, content) {
  if (mode === 'htmlmixed' || mode === 'html') {
    return html(content);
  }

  if (mode === 'javascript') {
    return js(content);
  }

  return content;
}

export default {
  html,
  js,
  format,
};

/**
 * Utility function for creating ISO-compliant dates
 */
exports.ISODateString = function(d) {
        function pad(n){
            return n<10 ? '0'+n : n;
        }
        if (typeof d === "string") d = new Date(d);
        return d.getUTCFullYear()+'-'
        + pad(d.getUTCMonth()+1)+'-'
        + pad(d.getUTCDate())+'T'
        + pad(d.getUTCHours())+':'
        + pad(d.getUTCMinutes())+':'
        + pad(d.getUTCSeconds())+'+00:00';
};

