    switch (
        value // 0 is Class Search Tab, 1 is Added Classes Tab, 2 is Map Tab
    ) {
        case 1:
            ReactGA.event({
                category: 'antalmanac-rewrite',
                action: `Switch tab to Added Classes`,
            });
            break;
        case 2:
            ReactGA.event({
                category: 'antalmanac-rewrite',
                action: `Switch tab to Map`,
            });
            break;
        default:
        // do nothing
    }

    dispatcher.dispatch({
        type: 'TAB_CHANGE',
        activeTab: value,
    });
};

