		r.splice( 'list', 0, 0, r.splice( 'list', 2, 1 ).result[0] );
		r.findAllComponents()[1].set( 'foo.baz', 10 );
		t.htmlEqual( fixture.innerHTML, '1-3|10-1|1-2|' );
	});

