	test( 'mapped observers shuffle correctly', t => {
		let rel;
		let stat;
		let relKey;
		let statKey;

		const cmp = Ractive.extend({
			onconfig () {
				this.observe( 'foo.bar', ( v, o, k ) => {
					rel = v;
					relKey = k;
				});
				this.observe( 'bar.bar', ( v, o, k ) => {
					stat = v;
					statKey = k;
				});
			}
		});
		const r = new Ractive({
			el: fixture,
