                        if (res.code != 0) {
                            dom.trigger('click');
                            form.render('checkbox');
                        }
                    });
                };
                if (this.checked) {
                    status = 1;
                }
                var confirm = $(this).attr('confirm');
                if (confirm === undefined) {
                    func();
                } else {
                    layer.confirm(confirm === 'undefined' ? '你确定要执行操作吗？' : confirm, {
                        title: false,
                        closeBtn: 0
                    }, function (index) {
                        func();
