it('maps code coverage against original source', () => {
  run('yarn', dir);
  const result = runJest(dir, ['--coverage', '--mapCoverage', '--no-cache']);

  expect(result.status).toBe(0);

  const coverageMapFile = path.join(coverageDir, 'coverage-final.json');
