function dxGetNextDiv(div)
{
    do
    {
        if (div.nextSibling)
        {
            div = div.nextSibling;
            if (div.tagName && div.tagName == "DIV" && div.style.display != "none")
                return div;
        }
    } while (div.nextSibling);
}

function dxGetPreviousDiv(div)
{
