        this.HousePlansService
            .downloadRemXml(this.housePlan)
            .then((response) => {
                this.downloadUrl = response;
                this.showDownloadModal = true;
            });
    }

    hideModalDownload () {
        this.showDownloadModal = false;
    }
}

