          <Stat data={this.props.data} />
        </div>
        </div>
        {
          this.props.children ?
            <div className="key-indicator__supporting-data">
              { this.props.children}
            </div>
          : null
        }
      </div>
    )
  }
}

export default KeyIndicator;

