    reset : function () {
        $('#outlib-search-keywords').textbox('clear');
        $('#outlib-search-date').combobox('clear').combobox('disableValidation');
        $('#outlib-search-date-from').datebox('clear');
        $('#outlib-search-date-to').datebox('clear');
        $('#outlib').datagrid('resetSort', {
