    slot: number,
    transaction: Transaction,
    meta: ConfirmedTransactionMeta | null,
  };

  declare export type ParsedAccountData = {
    program: string,
    parsed: any,
    space: number,
  };

  declare export type ParsedMessageAccount = {
    pubkey: PublicKey,
