function count ( $this ) {
    var current = parseInt( $this.html(), 10 );
    current = current + 1; /* Where 50 is increment */

    $this.html( ++current );
    if ( current > $this.data( "count" ) ) {
        $this.html( $this.data( "count" ) );
    } else {
        setTimeout( function () {
            count( $this );
        }, 50 );
    }
}

