#!/usr/bin/env node
const fs = require('fs')
const path = require('path')
const meow = require('meow')
const { build } = require('./lib/yaml-compose')

const cli = meow(`
  Usage
    $ yaml-compose <source>

  Options
    --output, -o Output directory

  Examples
    $ yaml-compose source
    $ yaml-compose source -o dist
`)

const source = cli.input[0]
const distDir = cli.flags.o || ''

if (!source) {
  console.log('Missing source')
  process.exit(1)
}

try {
  const yaml = build(source)

  if (distDir && !fs.existsSync(distDir)) {
    fs.mkdirSync(distDir)
  }

  fs.writeFileSync(path.join(process.cwd(), distDir, path.basename(source)), yaml)
} catch (err) {
  console.log('Failed to compose YAML file', err.message)
  process.exit(1)
}

// Define UI variables
const form = document.querySelector('#task-form');
const taskList = document.querySelector('.collection');
const clearBtn = document.querySelector('.clear-tasks');
const filter = document.querySelector('#filter');
const taskInput = document.querySelector('#task');

// Load all event listeners
loadEventListeners();

// Load all event listeners
function loadEventListeners() {
    // DOM load event
    document.addEventListener('DOMContentLoaded', getTasks);
    // Add task event
    form.addEventListener('submit', addTask);
    // Remove task event
    taskList.addEventListener('click', removeTask);
    // Clear task event
    clearBtn.addEventListener('click', clearTasks);
    // Filter tasks event
    filter.addEventListener('keyup', filterTasks);
}

// Get tasks from localStorage
function getTasks() {
    let tasks;
    if (localStorage.getItem('tasks') === null) {
        tasks = [];
    } else {
        tasks = JSON.parse(localStorage.getItem('tasks'));
    }

    tasks.forEach(function(task) {
        // Create li element
        const li = document.createElement('li');
        // Add class
        li.className = 'collection-item';
        // Create text node and append to li
        li.appendChild(document.createTextNode(task));
        // Create new link element
        const link = document.createElement('a');
        // Add class
        link.className = 'delete-item secondary-content';
        // Add icon html
        link.innerHTML = '<i class="fa fa-remove"></i>'
        // Append the link to li
        li.appendChild(link);

        // Append li to ul
        taskList.appendChild(li);
    });
}

// Add task
function addTask(event) {
    if (taskInput.value === '') {
        alert('Add a task');
        event.preventDefault();
        return;
    }

    // Create li element
    const li = document.createElement('li');
    // Add class
    li.className = 'collection-item';
    // Create text node and append to li
    li.appendChild(document.createTextNode(taskInput.value));
    // Create new link element
    const link = document.createElement('a');
    // Add class
    link.className = 'delete-item secondary-content';
    // Add icon html
    link.innerHTML = '<i class="fa fa-remove"></i>'
    // Append the link to li
    li.appendChild(link);

    // Append li to ul
    taskList.appendChild(li);

    // Store in LocalStorage
    storeTaskInLocalStorage(taskInput.value);

    // Clear input
    taskInput.value = '';

    event.preventDefault();
}

// Store task
function storeTaskInLocalStorage(task) {
    let tasks;
    if (localStorage.getItem('tasks') === null) {
        tasks = [];
    } else {
        tasks = JSON.parse(localStorage.getItem('tasks'));
    }

    tasks.push(task);

    localStorage.setItem('tasks', JSON.stringify(tasks));
}

// Remove task
function removeTask(event) {
    if(event.target.parentElement.classList.contains('delete-item')) {
        if (confirm('Are you sure?')) {
            event.target.parentElement.parentElement.remove();

            // Remove from localStorage
            removeTaskFromLocalStorage(event.target.parentElement.parentElement);
        }
    }
}

// Remove from localStorage
function removeTaskFromLocalStorage(taskItem) {
    let tasks;
    if (localStorage.getItem('tasks') === null) {
        tasks = [];
    } else {
        tasks = JSON.parse(localStorage.getItem('tasks'));
    }

    tasks.forEach(function(task, index) {
        if (taskItem.textContent === task) {
            tasks.splice(index, 1)
        }
    });

    localStorage.setItem('tasks', JSON.stringify(tasks));
}

// Clear tasks
function clearTasks(event) {
    // Way 1
    // taskList.innerHTML = '';

    // Way 2 (faster)
    while (taskList.firstChild) {
        taskList.removeChild(taskList.firstChild);
    }

    // Clear from localStorage
    clearTasksFromLocalStorage();
}

// Clear tasks from localStorage
function clearTasksFromLocalStorage() {
    localStorage.removeItem('tasks');
}

// Filter tasks
function filterTasks(event) {
    const text = event.target.value.toLowerCase();

    document.querySelectorAll('.collection-item').forEach(function(task) {
        const item = task.firstChild.textContent;
        if (item.toLowerCase().indexOf(text) != -1) {
            task.style.display = 'block';
        } else {
            task.style.display = 'none';
        }
    });

    console.log(text);
}

app.controller('clientMenuController', ['$scope', '$rootScope', '$state', 'LoginService', 'Order',
    function ($scope, $rootScope, $state, LoginService, Order) {

        processState($state.current.name);

        function processState(stateName) {
            switch (stateName) {
                case 'client.orders':
                    $scope.isOrders = true;
                    $scope.isDrinks = false;
                    $scope.isPizzas = false;
                    break;
                case 'client.drinks':
                    $scope.isOrders = false;
                    $scope.isDrinks = true;
                    $scope.isPizzas = false;
                    break;
                case 'client.pizzas':
                    $scope.isOrders = false;
                    $scope.isDrinks = false;
                    $scope.isPizzas = true;
                    break;
                default: break;
            }
        }

        $rootScope.$on('$stateChangeStart', function (event, toState) {
            processState(toState.name);
        });

        $scope.logout = function () {
            LoginService.unregisterClient();
            $state.go('login.client');
        }

    }
]);

