			return debugMode.indexOf(a[0] + ':' + typ) !== -1 ? true : false;
		} else {
			return debugMode.indexOf(primSel) !== -1 || debugMode.indexOf(typ) !== -1 ? true : false;
		}
	} else {
		if (debugMode.indexOf(':') !== -1) {
