                    $timeout(function() {
                        scope.progress = data;
                    });
                });
                scope.$on('track:id', function(event, data) {
                    $timeout(function() {
                        scope.currentPlaying = angularPlayer.currentTrackData();
                    });
                });
                scope.$on('currentTrack:position', function(event, data) {
                    $timeout(function() {
                        scope.currentPosition = $filter('humanTime')(data);
