const NotFoundPage = props => {
  const data = useStaticQuery(graphql`
    query {
      posts: allMdx(
        sort: { fields: [frontmatter___date], order: DESC }
        filter: { fileAbsolutePath: { regex: "//content/posts//" } }
        limit: 5
      ) {
        edges {
          node {
            excerpt
            frontmatter {
              date
              title
              tags
              slug
            }
          }
        }
      }
