// Motion Sensor
function deviceMotion(event) {
	if(motionLock) return;

	event.preventDefault();
	ac = event.acceleration;
	acg = event.accelerationIncludingGravity;
	rot = event.rotationRate;

	var d = new Date();  
	var f = 'HH:mm:ss.fff';  
	var strDt = comDateFormat(d, f);

	if(acg.y < -15){
		$('#detectmotion').html("RUN TO FORWARD!!!!!! : "+strDt);
		Publish("#forward");
		motionLock = true;
	}
	else if(acg.y > 15){
		$('#detectmotion').html("RUN TO BACK!!!!!! : "+strDt);
		Publish("#back"); 
		motionLock = true;
	}
	else if(acg.x < -10){
		$('#detectmotion').html("RUN TO RIGHT!!!!!! : "+strDt);
		Publish("#right"); 
		motionLock = true;
	}
	else if(acg.x > 10){
		$('#detectmotion').html("RUN TO LEFT!!!!!! : "+strDt);
		Publish("#left");
		motionLock = true;
	}

	if(motionLock){
		setTimeout(function(){
			motionLock = false;
	    }, 1500);
	}

	RenderHtml();
//	MQTT_Publish();
}

