            condition = commands['if'];
            file = commands['file'];
            oldText = commands['innerText'];
            type = commands['type'];

            if (condition == null || processor.checkCondition(condition)) {
                try {
                    result = null;
                    if (type == 'css') {
                        result = '<style type="text/css">' + (grunt.file.read(processor.replacePlaceHolder(file))) + '</style>';
