angular.module('os.biospecimen.participant.consents', [])
  .controller('ParticipantConsentsCtrl', function($scope, $sce, cpr, consent,
    PvManager,  DeleteUtil) {

    function init() {
      $scope.consentFormUploader = {};
      $scope.consentFormUrl = $sce.trustAsResourceUrl(cpr.getSignedConsentFormUrl());
      $scope.consent = consent;
      $scope.uploadMode = false;
      $scope.editMode = false;
      $scope.consentExists = $scope.consent.consentTierResponses.length > 0;

      loadPvs();
    }

    function loadPvs() {
      $scope.consentResponses = PvManager.getPvs('consent_response');
    }

    function deleteConsentForm() {
      cpr.deleteSignedConsentForm().then(
        function(result) {
          if (result) {
            $scope.consent.consentDocumentName = undefined;
          }
        }
      );
    }

    $scope.showUploadMode = function() {
      $scope.uploadMode = true;
    }

    $scope.cancel = function() {
      $scope.uploadMode = false;
    }

    $scope.uploadConsentForm = function() {
      $scope.consentFormUploader.ctrl.submit().then(
        function(fileName) {
          $scope.consent.consentDocumentName = fileName;
          $scope.uploadMode = false;
        }
      );
    }

    $scope.confirmDeleteConsentForm = function() {
      DeleteUtil.confirmDelete({
        entity: $scope.consent,
        templateUrl: 'modules/biospecimen/participant/confirm-delete-consent-form.html',
        delete: deleteConsentForm
      });
    }

    $scope.showEditConsents = function() {
      $scope.editMode = true;
    }

    $scope.saveConsents = function() {
      cpr.saveConsentResponse($scope.consent).then(function(result) {
        $scope.consents = result;
        $scope.editMode = $scope.consentResponseAdd = false;
      });
    }

    $scope.clearResponseSelection = function(consentTierResponse) {
      consentTierResponse.response = undefined;
    }

    init();
  });

import React from 'react'
import { graphql } from 'gatsby'
import Layout from '../components/Layout'
import CardList from '../components/CardList'
import Card from '../components/Card'
import Container from '../components/Container'
import SEO from '../components/SEO'
import PageTitle from '../components/PageTitle'

const Posts = ({ data, pageContext }) => {
  const posts = data.allContentfulPost.edges
  const { basePath } = pageContext
  let ogImage

  try {
    ogImage = posts[0].node.heroImage.ogimg.src
  } catch (error) {
    ogImage = null
  }

  return (
    <Layout>
      <SEO title="Paintings" image={ogImage} />
      <Container>
          <PageTitle small>
            All Paintings
          </PageTitle>
          <CardList>
            {posts.map(({ node: post }) => (
              <Card key={post.id} {...post} basePath={basePath} />
            ))}
          </CardList>
      </Container>
    </Layout>
  )
}

export const query = graphql`
  query($skip: Int!, $limit: Int!) {
    allContentfulPost(
      sort: { fields: [publishDate], order: DESC }
      limit: $limit
      skip: $skip
    ) {
      edges {
        node {
          title
          id
          slug
          publishDate(formatString: "MMMM DD, YYYY")
          heroImage {
            title
            fluid(maxWidth: 1800) {
              ...GatsbyContentfulFluid_withWebp_noBase64
            }
            ogimg: resize(width: 1800) {
              src
            }
          }
          metaDescription {
            internal {
              content
            }
          }
          body {
            childMarkdownRemark {
              timeToRead
              html
              excerpt(pruneLength: 80)
            }
          }
        }
      }
    }
  }
`

export default Posts

Template.schoolPage.onCreated(function() {
    var schoolId = this.data._id;
    Session.set('can-delete-'+schoolId, false);
});

Template.schoolPage.onRendered(function() {
    var schoolId = this.data._id || 'badId';
    var secrets = localStorage.getItem('secrets');
    secrets = secrets ? JSON.parse(secrets) : {};
    var secret = secrets[schoolId];
    Meteor.call('isSchoolCreator', schoolId, secret,
        function(err, result) {
            if (err) return Errors.throw(err.reason);
            Session.set('can-delete-'+schoolId, result);
        }
    );
});

Template.schoolPage.helpers({
    fmtRating: function() {
        if (!this) return '0/5, (0 ratings)';

        var fmtRating = (Math.round(100*this.rating)/20);
        fmtRating = (Math.round(10*fmtRating)/10)+'';
        if (fmtRating.length === 1) fmtRating += '.0';
        fmtRating += '/5';
        var s = this.numRatings === 1 ? '' : 's';
        return fmtRating+' ('+this.numRatings+' rating'+s+')';
    },

    numFountains: function() {
        if (!this || !this.fountains) return 0;
        return Object.keys(this.fountains).length;
    },

    canDelete: function() {
        var schoolId = this._id;
        return !!Session.get('can-delete-'+schoolId);
    }
});

Template.schoolPage.events({
    'click .delete-btn': function(e, tmpl) {
        e.preventDefault();

        if (confirm('Are you sure you want to delete this school?')) {
            var schoolId = this._id;
            var secrets = localStorage.getItem('secrets');
            secrets = secrets ? JSON.parse(secrets) : {};
            var secret = secrets[schoolId];
            if (secret) {
                Meteor.call('deleteSchool', schoolId, secret,
                    function(err, result) {
                        if (err) return Errors.throw(err.reason);

                        if (result.badSchoolId) {
                            return Errors.throw(
                                'The school id you provided is invalid.'
                            );
                        } else if (result.badSecret) {
                            return Errors.throw(
                                'You don\'t have permission to delete ' +
                                'this school.'
                            );
                        } else if (result.stillHasFountains) {
                            return Errors.throw(
                                'You can only delete schools with no ' +
                                'remaining fountains.'
                            );
                        } else if (result.success) {
                            Router.go('home');
                        }
                    }
                );
            } else {
                return Errors.throw(
                    'You don\'t have permission to delete this school.'
                );
            }
        }
    }
});

