    const s = scenario.map( (v,i) => {
      if (v === '' && i > 0) {
        return ':1s';
      }
      return v;
    }).join('\n').replace(/(\/\*[^*]*\*\/)|(\/\/.*)/g, '//').trim()
    this.props.playSpeech(s);
