        // Listening for a click on one of the radio buttons.
        // config.searchSite is either true or false.

        config.searchSite = this.id == 'searchSite';
    });


    function googleSearch(settings) {

        // If no parameters are supplied to the function,
        // it takes its defaults from the config object above:

        settings = $.extend({}, config, settings);
        settings.term = settings.term || $('#search').val();

        if (settings.searchSite) {
            // Using the Google site:example.com to limit the search to a
            // specific domain:
            settings.term = 'site:' + settings.siteURL + ' ' + settings.term;
        } else {
            settings.term = 'site:' + settings.blogURL + ' ' + settings.term;

        }

        // URL of Google's AJAX search API
        var apiURL = 'http://ajax.googleapis.com/ajax/services/search/' + settings.type + '?v=1.0&callback=?';
        var resultsDiv = $('#resultsDiv');

        $.getJSON(apiURL, {
            q: settings.term,
            rsz: settings.perPage,
            start: settings.page * settings.perPage
        }, function (r) {

            var results = r.responseData.results;
            $('#more').remove();

            if (results.length) {

                // If results were returned, add them to a pageContainer div,
                // after which append them to the #resultsDiv:

                var pageContainer = $('<div>', {className: 'pageContainer'});

                for (var i = 0; i < results.length; i++) {
                    // Creating a new result object and firing its toString method:
                    pageContainer.append(new result(results[i]) + '');
                }

                if (!settings.append) {
                    // This is executed when running a new search,
                    // instead of clicking on the More button:
                    resultsDiv.empty();
                }

                pageContainer.append('<div class="clear"></div>')
                    .hide().appendTo(resultsDiv)
                    .fadeIn('slow');

                var cursor = r.responseData.cursor;

                // Checking if there are more pages with results,
                // and deciding whether to show the More button:

                if (+cursor.estimatedResultCount > (settings.page + 1) * settings.perPage) {
                    $('<div>', {id: 'more'}).html('<div class="btn btn-default">More</div>').appendTo(resultsDiv).click(function () {
                        googleSearch({append: true, page: settings.page + 1});
                        $(this).fadeOut();
                    });
                }
                $('#searchModal').modal();

            }
            else {

                // No results were found for this search.

                resultsDiv.empty();
                $('<p>', {className: 'notFound', html: 'No Results Were Found!'}).hide().appendTo(resultsDiv).fadeIn();
                $('#searchModal').modal();
            }
        });
    }

    function result(r) {

        // This is class definition. Object of this class are created for
        // each result. The markup is generated by the .toString() method.

        var arr = [];

        // GsearchResultClass is passed by the google API
        switch (r.GsearchResultClass) {

            case 'GwebSearch':
                arr = [
                    '<div class="webResult">',
                    '<h2><a href="', r.unescapedUrl, '" target="_blank">', r.title, '</a></h2>',
                    '<p>', r.content, '<br><a href="', r.unescapedUrl, '" target="_blank">', r.visibleUrl, '</a></p>',
                    '</div>'
                ];
                break;
        }

        // The toString method.
        this.toString = function () {
            return arr.join('');
        }
    }

