    } catch (e) {
      resultElement.innerHTML = `検索中にエラーが発生しました: ${e.name}: ${e.message}`;
    }
  }

  document.getElementById("search-button").addEventListener("click", execute);
  document.getElementById("search-text").addEventListener("keypress", (event) => {
    if (event.key === "Enter") {
      execute();
    }
  });
