          }       
        var panel = new Ext.Panel({'title':"Gazetter", html: html, autoScroll: true})
        ltPanel.add(panel);
        ltPanel.doLayout();
        panel.expand();
        ltPanel.doLayout();
        this.panel = panel;
      }, 
