        for (let i in dinos) {
            if (this.best) {
                if (dinos[i].score > this.best.score)
                    this.best = dinos[i]
            } else {
                this.best = dinos[i]
            }
        }

        // this.best.log()

        const newBirds = []
        var bird = new Bird()
        bird.copy(this.best, true)
        newBirds.push(bird)

        for (let i = 0; i < POPULATION - 1; i++) {
