   * @param {Array} arr
   * @param {Number} k
   * @param {Function} compare
   * @private
   */


  function quickSelect(arr, k, compare) {
    if (k >= arr.length) {
      throw new Error('k out of bounds');
    } // check for NaN values since these can cause an infinite while loop


    for (var i = 0; i < arr.length; i++) {
      if (isNumeric(arr[i]) && isNaN(arr[i])) {
        return arr[i]; // return NaN
      }
    }

    var from = 0;
    var to = arr.length - 1; // if from == to we reached the kth element

    while (from < to) {
      var r = from;
      var w = to;
      var pivot = arr[Math.floor(Math.random() * (to - from + 1)) + from]; // stop if the reader and writer meets

      while (r < w) {
        // arr[r] >= pivot
        if (compare(arr[r], pivot) >= 0) {
          // put the large values at the end
          var tmp = arr[w];
          arr[w] = arr[r];
          arr[r] = tmp;
          --w;
        } else {
          // the value is smaller than the pivot, skip
          ++r;
        }
      } // if we stepped up (r++) we need to step one down (arr[r] > pivot)


      if (compare(arr[r], pivot) > 0) {
        --r;
      } // the r pointer is on the end of the first k elements


      if (k <= r) {
        to = r;
      } else {
        from = r + 1;
      }
    }

    return arr[k];
  }
});

const light = '{{ index .Site.Params.switch 1 }}'
const dark = '{{ index .Site.Params.switch 0 }}'
const comment = '{{ .Site.Params.comment }}'
const LIGHT = 'light', DARK = 'dark'

const themeSwitcher = document.getElementById('theme-switcher')

// set switcher
themeSwitcher.innerHTML = localStorage.theme === LIGHT ? light : dark

themeSwitcher.addEventListener('click', function () {
  const currentTheme = localStorage.theme
  const newTheme = currentTheme === LIGHT ? DARK : LIGHT

  // switch global theme
  switchMinimaTheme(currentTheme, newTheme)

  // switch utterance theme if necessary

  if (comment === 'utterances')
    switchUtteranceTheme(`github-${newTheme}`)
});

function switchMinimaTheme(oldTheme, newTheme) {
  const { classList } = document.documentElement
  const text = newTheme === LIGHT ? light : dark;

  classList.remove(oldTheme);
  classList.add(newTheme);
  localStorage.theme = newTheme;
  themeSwitcher.innerHTML = text;
}

const utteranceClassName = '.utterances-frame'
let utterance;

function switchUtteranceTheme(theme) {
  if (!utterance) utterance = document.querySelector(utteranceClassName)
  utterance.contentWindow.postMessage({type: 'set-theme', theme}, 'https://utteranc.es')
}

'use strict';

const { performance } = require('perf_hooks');

/**
 * Request context Logger, itself isn't a {@link Logger}.
 */
class ContextLogger {

  /**
   * @class
   * @param {Context} ctx - egg Context instance
   * @param {Logger} logger - Logger instance
   */
  constructor(ctx, logger) {
    this.ctx = ctx;
    this._logger = logger;
  }

  get paddingMessage() {
    const ctx = this.ctx;

    // Auto record necessary request context infomation, e.g.: user id, request spend time
    // format: '[$userId/$ip/$traceId/$use_ms $method $url]'
    const userId = ctx.userId || '-';
    const traceId = ctx.tracer && ctx.tracer.traceId || '-';
    let use = 0;
    if (ctx.performanceStarttime) {
      use = Math.floor((performance.now() - ctx.performanceStarttime) * 1000) / 1000;
    } else if (ctx.starttime) {
      use = Date.now() - ctx.starttime;
    }
    return '[' +
      userId + '/' +
      ctx.ip + '/' +
      traceId + '/' +
      use + 'ms ' +
      ctx.method + ' ' +
      ctx.url +
    ']';
  }

  write(msg) {
    this._logger.write(msg);
  }
}

[ 'error', 'warn', 'info', 'debug' ].forEach(level => {
  const LEVEL = level.toUpperCase();
  ContextLogger.prototype[level] = function() {
    const meta = {
      formatter: contextFormatter,
      paddingMessage: this.paddingMessage,
      ctx: this.ctx,
    };
    this._logger.log(LEVEL, arguments, meta);
  };
});

module.exports = ContextLogger;

function contextFormatter(meta) {
  return meta.date + ' ' + meta.level + ' ' + meta.pid + ' ' + meta.paddingMessage + ' ' + meta.message;
}

var request = require('request')
var httpService = {}

httpService.request = async (ctx, _method, _url, data) => {
  if (!data) {
    data = {}
  }
  data.requestIP = ctx.request.ip
  var _headers = {}
  _headers['user-agent'] = ctx.header['user-agent']
  _headers['cookie'] = ctx.header['cookie']

  var options = {
    method: _method,
    url: _url,
    headers: _headers,
    form: data
  }
  return new Promise((resolve, reject) => {
    request(options, function (error, response, body) {
      var cookies = response.headers['set-cookie']
      if (cookies !== undefined) {
        ctx.set('set-cookie', cookies)
      }
      const res = JSON.parse(body)
      if (!error && response.statusCode === 200) {
        resolve(res)
      } else {
        resolve(res)
      }
    })
  })
}

export default httpService

