function setTree() {
  var Source = [{
    title: "Kasus",
    folder: true,
    children: setKasus(),
    checkbox: false
  }];

  $("#tree").fancytree({
    checkbox: true,
    source: Source,
    lazyLoad: function(event, data) {
        var node = data.node;
        data.result = setTarget(node.key);
    },
    selectMode: 2,
    select: function(event, data) {
      // Display list of selected nodes
      var selNodes = data.tree.getSelectedNodes();
      // convert to title/key array
      var selKeys = $.map(selNodes, function(node) {
        return parseInt(node.key);
      });
      tap_id = selKeys;
      var selTitles = $.map(selNodes, function(node) {
        return node.title;
      });
      var selTanggalStatus = $.map(selNodes, function(node) {
        return node.data.tanggal_status;
      });
      tanggal_status = selTanggalStatus;

      let $ul = $('.selected');
      $ul.html('');
      $ul.append(
        selTitles.map(title =>
          $("<li>").html(title)
        )
      );
    },
  });
  $(".fancytree-container").addClass("fancytree-connectors");
  $(".fancytree-container").css("font-size", "12pt");
}

