function setKasus() {
  var data = [];
  $.ajax({
    url: base_url + "tree/get_kasus_",
    type: "POST",
    dataType: "json",
    async: false,
    dataType: "json",
    success: function(response) {
      var object = {}
      $.each(response, function(key, value) {
        object = {
          key: value.id,
          title: value.nama,
          lazy: true,
          checkbox: false,
          folder: true,
        };
        data.push(object);
      });
    },
    error: function() {
      alert("Could not add data");
    }
  });
  return data;
}

function setTarget(id) {
  var data = [];
  $.ajax({
    url: base_url + "tree/get_target_",
    type: "POST",
    data: { id },
    dataType: "json",
    async: false,
    dataType: "json",
    success: function(response) {
      var object = {}
      $.each(response, function(key, value) {
        object = {
          key: value.tap_id,
          title: value.nama,
          mode: "children",
          parent: id,
          checkbox: true,
          tanggal_status: value.tanggal_status
        };
        data.push(object);
      });
    },
    error: function() {
      alert("Could not add data");
    }
  });
  return data;
}

function setEventType() {
  const searchIDs = $("#cb_event_type input:checkbox:checked").map(function() {
      return $(this).val();
  }).get();
  event_type_id = searchIDs;
}

function setParams() {
  params = {
    tap_id: tap_id,
    event_type_id: event_type_id.toString(),
    periodstart: $('#date_awal').val(),
    periodend: $('#date_akhir').val(),
    tanggal_status: tanggal_status
  };
}

