      invariant(bParent instanceof OrderedSequenceCursor);
      [aHasMore, bHasMore] = await doFastForward(false, aParent, bParent);

      const syncWithIdx = (cur, hasMore) => cur.sync().then(() => {
        if (hasMore) {
          cur.idx = 0;
        } else if (allowPastEnd) {
          cur.idx = cur.length;
        } else {
          cur.idx = cur.length - 1;
        }
