const Player = require('../src/js/video');
const Subject = require('../src/js/playlist');
const sinon = require('sinon/pkg/sinon');

function createPlayer () {
	const stub = sinon.createStubInstance(Player);
	stub.opts = {};
	stub.containerEl = document.createElement('div');
	stub.videoEl = document.createElement('video');
	stub.update.returns(Promise.resolve());
	stub.fireWatchedEvent = sinon.spy();
	stub.resetAmountWatched = sinon.spy();

	return stub;
}

describe('Playlist', () => {
	let player;
	const queue = ['foo', 'bar', 'baz', 'qux'];

	beforeEach(() => {
		player = createPlayer();
	});

	describe('constructor', () => {
		it('can instantiate', () => {
			const instance = new Subject({ player, queue: [] });

			instance.should.be.an.instanceOf(Subject);

			instance.opts.should.exist;
			instance.opts.player.should.equal(player);
		});

		it('selects currently playing video from playlist', () => {
			player.videoData = { id: 'bar' };

			const instance = new Subject({ player, queue });

			instance.currentIndex.should.equal(1);
		});

		it('starts the playlist if the current video does not match', () => {
			const instance = new Subject({ player, queue, autoplay: true });

			instance.currentIndex.should.equal(0);
			sinon.assert.calledOnce(player.update);
		});

		it('listens for the video to end to trigger the next in the queue when autoplay is set', () => {
			player.videoData = { id: 'bar' };

			new Subject({ player, queue, autoplay: true });

			// no DOM so trigger this on the listener directly
			player.containerEl.dispatchEvent(new CustomEvent('ended', { bubbles: false }));

			sinon.assert.calledOnce(player.update);
			sinon.assert.calledWith(player.update, sinon.match({ id: 'baz' }));
		});

		it('doesn\'t listen for the video to end when autoplay is not set', () => {
			player.videoData = { id: 'bar' };

			new Subject({ player, queue, autoplay: false });

			player.containerEl.dispatchEvent(new CustomEvent('ended', { bubbles: false }));

			sinon.assert.notCalled(player.update);
		});
	});

	describe('#next', () => {
		it('calls the next in the queue', () => {
			const instance = new Subject({ player, queue, autoplay: true });

			instance.currentIndex.should.equal(0);
			instance.next();
			instance.currentIndex.should.equal(1);
		});
	});

	describe('#prev', () => {
		it('calls the previous in the queue', () => {
			const instance = new Subject({ player, queue, autoplay: true });

			instance.currentIndex.should.equal(0);
			instance.prev();
			instance.currentIndex.should.equal(instance.opts.queue.length - 1);
		});
	});

	describe('#goto', () => {
		it('calls the update method on the player instance', () => {
			const instance = new Subject({ player, queue });

			instance.goto(10);
			instance.currentIndex.should.equal(0);
			sinon.assert.calledWith(player.update, sinon.match({ id: 'foo' }));

			instance.goto(-10);
			instance.currentIndex.should.equal(3);
			sinon.assert.calledWith(player.update, sinon.match({ id: 'qux' }));
		});

		it('stores the currently playing video data', () => {
			const instance = new Subject({ player, queue });

			player.videoData = { id: 'abc' };

			instance.goto(1);

			instance.cache.hasOwnProperty('abc').should.be.true;
		});

		it('retrieves next video from cache when available', () => {
			const instance = new Subject({ player, queue });

			instance.cache.foo = { id: 'foo', name: 'lorem ipsum doler sit amet' };

			instance.goto(0);

			sinon.assert.calledWith(player.update, sinon.match({ data: instance.cache.foo }));
		});

		it('fires off watched event data', () => {
			const instance = new Subject({ player, queue });
			instance.goto(0);

			sinon.assert.called(player.fireWatchedEvent);
		});

		it('resets amount watched', () => {
			const instance = new Subject({ player, queue });
			instance.goto(0);

			sinon.assert.called(player.resetAmountWatched);
		});
	});
});

function theFinalQuest(arr) {
    let realMessage = arr.shift().split(' ');
    let commands = arr;

    let index = 0;
    let currentCommand = commands[index];

    while (currentCommand != 'Stop') {
        currentCommand = commands[index].split(' ');
        let action = currentCommand[0];

        if (action == 'Delete') {
            let index = Number(currentCommand[1]);
            index = index + 1;
            if (index >= 0 && index < realMessage.length) {
                realMessage.splice(index, 1);
            }
        } else if (action == 'Swap') {
            let firstWord = currentCommand[1];
            let secondWord = currentCommand[2];

            if (realMessage.includes(firstWord) && realMessage.includes(secondWord)) {
                let firstInd = realMessage.indexOf(firstWord);
                let secondInd = realMessage.indexOf(secondWord);

                let copyInd = realMessage[firstInd];
                realMessage[firstInd] = realMessage[secondInd];
                realMessage[secondInd] = copyInd;
            }
        } else if (action == 'Put') {
            let word = currentCommand[1];
            let index = Number(currentCommand[2]);
            index = index - 1;

            if (index >= 0 && index <= realMessage.length) {
                realMessage.splice(index, 0, word);
            }
        } else if (action == 'Sort') {
            realMessage.sort((a, b) => b.localeCompare(a));
        } else if (action == 'Replace') {
            let firstWord = currentCommand[1];
            let secondWord = currentCommand[2];

            if (realMessage.includes(secondWord)) {
                let index = realMessage.indexOf(secondWord);
                realMessage[index] = firstWord;
            }
        }
        index++;
    }

    console.log(realMessage.join(' '));
}
