function metricsToDataRows(metrics) {
  return metrics.map(function(metric) {
    return [ metric.times_changed, metric.flog, tooltip(metric) ]
  });
}

function tooltip(metric) {
  return metric.file +
    "\nTimes Changed: " +
    metric.times_changed +
    "\nFlog: " +
    metric.flog
}

