			return this.days[this.getDay()].substring(0, 3)
		},
		j : function() {
			return this.getDate()
		},
		l : function() {
			return this.days[this.getDay()]
		},
		N : function() {
			return this.getDay() + 1
		},
		S : function() {
			return this.suffix[this.getDate()] || 'th'
		},
		w : function() {
			return this.getDay()
		},
		z : function() {
			return Math.round((this - this.f()) / 864e5)
		},
		// Week
		W : function() {
			return Math
					.ceil(((((this - this.f()) / 864e5) + this.f().w()) / 7))
		},
		// Month
		F : function() {
			return this.months[this.getMonth()];
		},
		m : function() {
			return (this.getMonth() + 1).pad(0)
		},
		M : function() {
			return this.months[this.getMonth()].substring(0, 3)
		},
		n : function() {
			return this.getMonth() + 1
		},
		// Year
		L : function() {
			var Y = this.Y();
			return Y % 4 ? false : Y % 100 ? true : Y % 400 ? false : true
		},
		f : function() {
			return new Date(this.getFullYear(), 0, 1)
		},
		Y : function() {
			return this.getFullYear()
		},
		y : function() {
			return ('' + this.getFullYear()).substr(2)
		},
		// Time
		a : function() {
			return this.getHours() < 12 ? 'am' : 'pm'
		},
		A : function() {
			return this.a().toUpperCase()
		},
		B : function() {
			return Math.floor((((this.getHours()) * 36e5)
					+ (this.getMinutes() * 6e4) + (this.getSeconds() * 1e3))
					/ 864e2).pad(0, 3)
		},
		g : function() {
			return this.getHours() % 12 || 12
		},
		G : function() {
			return this.getHours()
		},
		h : function() {
			return this.g().pad('0')
		},
		H : function() {
			return this.getHours().pad('0')
		},
		i : function() {
			return this.getMinutes().pad(0)
		},
		s : function() {
			return this.getSeconds().pad('0')
		},
		u : function() {
			return this.getTime() % 1000
		},
		// Timezone
		O : function() {
			var t = this.getTimezoneOffset() / 60;
			return (t >= 0 ? '+' : '-') + Math.abs(t).pad(0).rpad(0, 4)
		},
		P : function() {
			var t = this.O();
			return t.substr(0, 3) + ':' + t.substr(3)
		},
		Z : function() {
			return this.getTimezoneOffset() * 60;
		},
		// Full Date/Time
		c : function() {
			return this.Y() + '-' + this.m() + '-' + this.d() + 'T' + this.H()
					+ ':' + this.i() + ':' + this.s() + this.P()
		},
		r : function() {
			return this.toString()
		},
		U : function() {
			return this.getTime() / 1000
		}
	});

})(jQuery);

