    this.data.push({
      type: 'move',
      item: { direction: 'up', value }
    });
  }

  moveDown(value = 1) {
    this.data.push({
      type: 'move',
      item: { direction: 'down', value }
    });
  }

  addIcon(icon, style = null, options = null) {
    this.data.push({
      type: 'icon',
      item: { icon, style, options }
    });
  }

  addImage(image, options = {}) {
    this.data.push({
      type: 'image',
      item: { image, options }
    });
  }

