      this.webUris();
      this.redirectUris();
      this.normalizeNativeAppUris();

        // MAX AGE FORMAT
      if (this.default_max_age !== undefined) {
        if (!Number.isInteger(this.default_max_age) || this.default_max_age <= 0) {
          invalidate('default_max_age must be a positive integer');
        }
      }

      const rts = _.chain(this.response_types)
        .map(rt => rt.split(' '))
        .flatten()
        .uniq()
        .value();

      if (this.token_endpoint_auth_method === 'none') {
        if (_.includes(this.grant_types, 'authorization_code')) {
          invalidate('grant_types must not use token endpoint when token_endpoint_auth_method is none');
        }
      }

      if (_.includes(rts, 'code') && !_.includes(this.grant_types, 'authorization_code')) {
        invalidate('grant_types must contain authorization_code when code is amongst response_types');
      }

      if (_.includes(rts, 'token') || _.includes(rts, 'id_token')) {
        if (!_.includes(this.grant_types, 'implicit')) {
          invalidate('grant_types must contain implicit when id_token or token are amongst response_types');
        }
      }

        // CLIENT SECRET LENGHT
      const hsLengths = SECRET_LENGTH_REQUIRED.map((prop) => {
        if (this[prop] && this[prop].startsWith('HS')) {
          return parseInt(this[prop].slice(-3) / 8, 10);
        }

        return undefined;
      });

      const validateSecretLength = _.max(hsLengths);

      const validateSecretPresence = validateSecretLength ||
        ['private_key_jwt', 'none'].indexOf(this.token_endpoint_auth_method) === -1;

      if (validateSecretPresence && !this.client_secret) {
        invalidate('client_secret is mandatory property');
      }

      if (validateSecretLength) {
        if (this.client_secret.length < validateSecretLength) {
          invalidate('insufficient client_secret length');
        }
      }

        // PAIRWISE PRESENCE
      if (this.subject_type === 'pairwise' && !this.sector_identifier_uri) {
        const hosts = _.chain(this.redirect_uris)
          .map(uri => url.parse(uri).host)
          .uniq()
          .value();

        if (hosts.length === 1) {
          this.sector_identifier = hosts[0];
        } else {
          invalidate('sector_identifier_uri is required when using multiple hosts in your redirect_uris');
        }
      } else if (this.sector_identifier_uri) {
        this.sector_identifier = url.parse(this.sector_identifier_uri).host;
      }

      if (this.jwks !== undefined && this.jwks_uri !== undefined) {
        invalidate('jwks and jwks_uri must not be used at the same time');
      }

      if (this.jwks !== undefined) {
        if (!Array.isArray(this.jwks.keys)) {
          invalidate('jwks must be a JWK Set');
        }
        if (!this.jwks.keys.length) {
          invalidate('jwks.keys must not be empty');
        }
      }
    }

    required() {
      REQUIRED.forEach((prop) => {
        if (!this[prop]) {
          invalidate(`${prop} is mandatory property`);
        }
      });

      const requireJwks = this.token_endpoint_auth_method === 'private_key_jwt' ||
        (String(this.request_object_signing_alg).match(/^(RS|ES)/)) ||
        (String(this.id_token_encrypted_response_alg).match(/^(RSA|ECDH)/)) ||
        (String(this.userinfo_encrypted_response_alg).match(/^(RSA|ECDH)/));

      if (requireJwks && !this.jwks && !this.jwks_uri) {
        invalidate('jwks or jwks_uri is mandatory for this client');
      }
    }

    strings() {
      STRING.forEach((prop) => {
        if (this[prop] !== undefined) {
          const isAry = ARYS.indexOf(prop) !== -1;
          (isAry ? this[prop] : [this[prop]]).forEach((val) => {
            if (typeof val !== 'string' || !val.length) {
              invalidate(isAry ?
                `${prop} must only contain strings` :
                `${prop} must be a non-empty string if provided`);
            }
          });
        }
      });
    }

    webUris() {
      WEB_URI.forEach((prop) => {
        if (this[prop] !== undefined) {
          const isAry = ARYS.indexOf(prop) !== -1;
          (isAry ? this[prop] : [this[prop]]).forEach((val) => {
            const method = HTTPS_URI.indexOf(prop) === -1 ? 'isWebUri' : 'isHttpsUri';
            const type = method === 'isWebUri' ? 'web' : 'https';
            if (!validUrl[method](val)) {
              invalidate(isAry ?
                `${prop} must only contain ${type} uris` :
                `${prop} must be a ${type} uri`);
            }
          });
        }
      });
    }

    arrays() {
      ARYS.forEach((prop) => {
        if (this[prop] !== undefined) {
          if (!Array.isArray(this[prop])) {
            invalidate(`${prop} must be an array`);
          }
          this[prop] = _.uniq(this[prop]);
        }
      });
    }

    lengths() {
      if (LENGTH.every(prop => this[prop] && this[prop].length === 0)) {
        return;
      }
      LENGTH.forEach((prop) => {
        if (this[prop] !== undefined && !this[prop].length) {
          invalidate(`${prop} must contain members`);
        }
      });
    }

    booleans() {
      BOOL.forEach((prop) => {
        if (this[prop] !== undefined) {
          if (typeof this[prop] !== 'boolean') {
            invalidate(`${prop} must be a boolean`);
          }
        }
      });
    }

    whens() {
      _.forEach(WHEN, (then, when) => {
        if (this[when] !== undefined && this[then[0]] === undefined) {
          invalidate(`${then[0]} is mandatory property`);
        } else if (this[when] === undefined && this[then[0]] !== undefined) {
          this[when] = then[1];
        }
      });
    }

    enums() {
      _.forEach(ENUM, (only, prop) => {
        if (typeof only === 'function') {
          only = only(this); // eslint-disable-line no-param-reassign
        }

        if (this[prop] !== undefined) {
          const isAry = ARYS.indexOf(prop) !== -1;
          if (isAry && this[prop].some((val) => {
            if (only instanceof Set) {
              return !only.has(val);
            }
            return only.indexOf(val) === -1;
          })) {
            invalidate(`${prop} can only contain members [${only}]`);
          } else if (!isAry && only.indexOf(this[prop]) === -1) {
            invalidate(`${prop} must be one of [${only}]`);
          }
        }
      });
    }

    normalizeNativeAppUris() {
      if (this.application_type === 'web') return;
      if (!instance(provider).configuration('features.oauthNativeApps')) return;

      this.redirect_uris = _.map(this.redirect_uris, (redirectUri) => {
        const parsed = url.parse(redirectUri);
        // remove the port component, making dynamic ports allowed for loopback uris
        if (parsed.protocol === 'http:' && LOOPBACKS.indexOf(parsed.hostname) !== -1) {
          return url.format(Object.assign(parsed, {
            host: null,
            port: null,
          }));
        }

        return redirectUri;
      });
    }

    redirectUris() {
      this.redirect_uris.forEach((redirectUri) => {
        if (redirectUri.indexOf('#') !== -1) {
          invalidate('redirect_uris must not contain fragments');
        }

        switch (this.application_type) { // eslint-disable-line default-case
          case 'web':
            if (!validUrl.isWebUri(redirectUri)) {
              invalidate('redirect_uris must only contain valid web uris');
            }

            if (this.grant_types.indexOf('implicit') !== -1 && redirectUri.startsWith('http:')) {
              invalidate('redirect_uris for web clients using implicit flow MUST only register URLs using the https scheme');
            }

            // if (url.parse(redirectUri).hostname === 'localhost') {
            //   invalidate('redirect_uris for web clients must not be using localhost');
            // }
            if (this.grant_types.indexOf('implicit') !== -1 && url.parse(redirectUri).hostname === 'localhost') {
                invalidate('redirect_uris for web clients using implicit flow must not be using localhost');
            }
            break;
          case 'native':
            if (!validUrl.isUri(redirectUri)) {
              invalidate('redirect_uris must only contain valid uris');
            }

            if (instance(provider).configuration('features.oauthNativeApps')) {
              const uri = url.parse(redirectUri);

              switch (uri.protocol) {
                case 'http:': // Loopback URI Redirection
                  if (LOOPBACKS.indexOf(uri.hostname) === -1) {
                    invalidate('redirect_uris for native clients using http as a protocol can only use loopback addresses as hostnames');
                  }
                  break;
                case 'https:': // App-claimed HTTPS URI Redirection
                  if (LOOPBACKS.indexOf(uri.hostname) !== -1) {
                    invalidate(`redirect_uris for native clients using claimed HTTPS URIs must not be using ${uri.hostname} as hostname`);
                  }
                  break;
                default: // App-declared Custom URI Scheme Redirection
              }
            } else {
              if (redirectUri.startsWith('https:')) {
                invalidate('redirect_uris for native clients must not be using https URI scheme');
              }

              if (redirectUri.startsWith('http:') && url.parse(redirectUri).hostname !== 'localhost') {
                invalidate('redirect_uris for native clients must be using localhost as hostname');
              }
            }
            break;
        }
      });
    }
  }

  return Schema;
};

// @flow

import type {
  DiskletFile,
  DiskletFolder,
  EdgeIo
} from '../../edge-core-index.js'
import { decrypt, encrypt } from '../../util/crypto/crypto.js'
import { utf8 } from '../../util/encoding.js'

/**
 * A file within an encrypted folder.
 */
class RepoFile {
  io: EdgeIo
  dataKey: Uint8Array
  file: DiskletFile

  constructor (io: EdgeIo, dataKey: Uint8Array, file: DiskletFile) {
    this.io = io
    this.dataKey = dataKey
    this.file = file
  }

  delete () {
    return this.file.delete()
  }

  getData (): Promise<Uint8Array> {
    return this.file
      .getText()
      .then(text => JSON.parse(text))
      .then(json => decrypt(json, this.dataKey))
  }

  getText (): Promise<string> {
    return this.getData().then(data => utf8.stringify(data))
  }

  setData (data: Array<number> | Uint8Array): Promise<void> {
    const dataCast: any = data // Treating Array<number> like Uint8Array
    return this.file.setText(
      JSON.stringify(encrypt(this.io, dataCast, this.dataKey))
    )
  }

  setText (text: string): Promise<void> {
    return this.setData(utf8.parse(text))
  }
}

/**
 * Wraps a folder with automatic encryption and decryption.
 */
export class RepoFolder {
  io: EdgeIo
  dataKey: Uint8Array
  inner: DiskletFolder

  constructor (io: EdgeIo, dataKey: Uint8Array, folder: DiskletFolder) {
    this.io = io
    this.dataKey = dataKey
    this.inner = folder
  }

  delete () {
    return this.inner.delete()
  }

  file (name: string): DiskletFile {
    return new RepoFile(this.io, this.dataKey, this.inner.file(name))
  }

  folder (name: string): DiskletFolder {
    return new RepoFolder(this.io, this.dataKey, this.inner.folder(name))
  }

  listFiles () {
    return this.inner.listFiles()
  }

  listFolders () {
    return this.inner.listFolders()
  }
}

import React, { Component } from 'react';
import {
    View,
    Text,
    TouchableHighlight,
    TouchableOpacity,
    StyleSheet,
    TextInput,
    Alert,
} from 'react-native';
import DropDownPicker from 'react-native-dropdown-picker';
import { db } from '../config';
import firebase from 'firebase'
import 'firebase/storage';
import uuid from 'react-native-uuid';
import ResourceImagePicker from "../components/ResourceImagePicker"
import * as Permissions from 'expo-permissions';
import Constants from 'expo-constants';
import { KeyboardAwareScrollView } from 'react-native-keyboard-aware-scroll-view'
import DateTimePickerModal from "react-native-modal-datetime-picker";
import moment from 'moment'
import Icon from "react-native-vector-icons/MaterialCommunityIcons";
import { AsyncStorage } from "react-native"

class Edit extends Component {
    constructor() {
        super()
        this.state = {
            // Sets the visibility of the date picker
            isVisible: false
        }
    }
    state = {
        name: '',
        author: firebase.auth().currentUser.uid,
        category: '',
        time: firebase.database.ServerValue.TIMESTAMP,
        description: '',
        location: '',
        expiry: '',
        imageUri: '',
    };

    // Shows the date picker
    showPicker = () => {
        this.setState({ isVisible: true })
    };

    // Hides the date picker and resets expiry (users have to press confirm to save their changes)
    hidePicker = () => {
        this.setState({
            isVisible: false,
            expiry: ''
        })
    }

    // Hides the date picker and sets the state of expiry to the date the user has picked
    handlePicker = (date) => {
        this.setState({
            isVisible: false,
            expiry: moment(date).format('MMMM Do YYYY')
        })
    }

    // Sets all the inputs to the correct values from the offer itself
    componentDidMount = async () => {
        this.getPermissionAsync();
        const { navigation } = this.props;

        const name = navigation.getParam('name', 'no name');
        this.setState({ name })

        const uid = navigation.getParam('uid', 'no uid')
        this.setState({ uid })

        const key = navigation.getParam('key', 'no key')
        this.setState({ key })

        const description = navigation.getParam('description', 'no description');
        this.setState({ description })

        const category = ''
        this.setState({ category })

        const expiry = navigation.getParam('expiry', 'no expiry');
        this.setState({ expiry })

        const location = ''
        this.setState({ location })

        const time = navigation.getParam('time', 'no time')
        this.setState({ time })

        const imageID = navigation.getParam('imageID', 'no imageID')
        const ref = firebase.storage().ref('offers/' + { imageID }.imageID + '.jpg');
        const url = await ref.getDownloadURL();
        this.setState({ image: url, imageUri: url })
    }

    // Gets permission to access the camera roll
    getPermissionAsync = async () => {
        if (Constants.platform.ios) {
            console.log('getting permission');
            const { status } = await Permissions.askAsync(Permissions.CAMERA_ROLL);
            if (status !== 'granted') {
                alert('Sorry, we need camera roll permissions to make this work!');
            }
        }
    }

    // Updates the offer in Firebase with the new values
    editOffer(name, category, description, location, expiry, id) {
        db.ref('offers/' + this.state.key).update({
            name: name,
            category: category,
            description: description,
            location: location,
            expiry: expiry,
            id: id
        });
    };

    // Sets this.state.imageUri to the uri that is passed
    setOfferImage = (uri) => {
        this.setState({ imageUri: uri.uri })
    }

    // Alerts the user if they have not filled out one of the fields
    // If all fields are filled, uploads the offer to Firebase along with the blob of the image
    handleSubmit = () => {
        // Checks if an image has been selected
        if (!(/\S/.test(this.state.imageUri))) {
            Alert.alert(
                "Please add an image for your offer"
            );
        }

        // Checks if the other inputs have been filled
        else if (!(/\S/.test(this.state.name)) || !(/\S/.test(this.state.category)) || !(/\S/.test(this.state.description)) || !(/\S/.test(this.state.location))) {
            Alert.alert(
                "Please fill in all the fields before submitting"
            );
        }
        else {
            this.uriToBlob(this.state.imageUri).then((blob) => {
                return this.uploadToFirebase(blob);
            });
        }
    };

    // Converts the URI to a blob that can be stored in Firebase Storage
    uriToBlob = (uri) => {
        console.log('uri: ' + uri)
        return new Promise(function (resolve, reject) {
            try {
                var xhr = new XMLHttpRequest();
                xhr.open("GET", uri);
                xhr.responseType = "blob";
                xhr.onerror = function () { reject("Network error.") };
                xhr.onload = function () {
                    if (xhr.status === 200) { resolve(xhr.response) }
                    else { reject("Loading error:" + xhr.statusText) }
                };
                xhr.send();
            }
            catch (err) { reject(err.message) }
        })
    }

    // Uploads the offer to Firebase along with the blob
    uploadToFirebase = (blob) => {
        console.log('uploading to firebase')
        return new Promise((resolve, reject) => {
            var storageRef = firebase.storage().ref();

            // Generates a random and unique ID for the image
            const imageUuid = uuid.v1();
            console.log('uuid: ' + imageUuid)

            AsyncStorage.setItem('imageLoaded', 'not loaded')

            // Stores the blob as an image in Firebase Storage under the previously generated UUID
            storageRef.child('offers/' + imageUuid + '.jpg').put(blob, {
                contentType: 'image/jpeg'
            }).then((snapshot) => {
                AsyncStorage.setItem('imageLoaded', 'loaded')
                blob.close();
                resolve(snapshot);
            }).catch((error) => {
                reject(error);
            });

            // Edits the offer and updates the relevant values
            this.editOffer(this.state.name, this.state.category, this.state.description, this.state.location, this.state.expiry, imageUuid);
            Alert.alert('Offer saved successfully');

            this.props.navigation.navigate('Offer', {
                name: this.state.name,
                key: this.state.key,
                uid: this.state.uid,
                description: this.state.description,
                category: this.state.category,
                expiry: this.state.expiry,
                location: this.state.location,
                time: this.state.time,
                imageID: this.state.imageID
            })
        });
    }

    render() {
        return (
            <KeyboardAwareScrollView
                style={{ backgroundColor: 'white', padding: 30 }}
                resetScrollToCoords={{ x: 0, y: 0 }}
                contentContainerStyle={styles.container}
                scrollEnabled={true}
            >
                <View style={{ flexDirection: 'row' }}>
                    <Icon
                        name="arrow-left"
                        color='grey'
                        size={30}
                        onPress={() => this.props.navigation.goBack()}
                        style={{ marginTop: 30 }}
                    />
                    <Text style={styles.title}>Edit Offer</Text>
                </View>
                <ResourceImagePicker image={this.state.image} onImagePicked={this.setOfferImage} />
                <Text style={styles.heading}>Offer Title</Text>
                <View style={[styles.inputView]}>
                    <TextInput
                        style={styles.inputText}
                        placeholder="Name your offer"
                        autoCorrect={true}
                        onChangeText={name => this.setState({ name })}
                        value={this.state.name}
                    />
                </View>
                <Text style={styles.heading}>Select a Category</Text>
                <DropDownPicker
                    zIndex={5000}
                    items={[
                        { label: 'Appliances', value: 'Appliances' },
                        { label: 'Babies and Kids', value: 'Babies and Kids' },
                        { label: 'Books', value: 'Books' },
                        { label: 'Clothing', value: 'Clothing' },
                        { label: 'Electronics', value: 'Electronics' },
                        { label: 'Food', value: 'Food' },
                        { label: 'Furniture', value: 'Furniture' },
                        { label: 'Health', value: 'Health' },
                        { label: 'Stationery', value: 'Stationery' },
                        { label: 'Hobbies', value: 'Hobbies' },
                        { label: 'Sports', value: 'Sports' },
                        { label: 'Toys and Games', value: 'Toys and Games' }
                    ]}
                    placeholder="Select a category"
                    defaultNull={this.state.category === ''}
                    containerStyle={styles.dropdown}
                    style={{ backgroundColor: 'white', borderTopLeftRadius: 25, borderTopRightRadius: 25, borderBottomLeftRadius: 25, borderBottomRightRadius: 25, padding: 20 }}
                    dropDownStyle={{ backgroundColor: 'white', borderBottomLeftRadius: 25, borderBottomRightRadius: 25 }}
                    placeholderStyle={{ color: "#c9c9c9", position: 'absolute', left: 0 }}
                    labelStyle={{ color: "#c9c9c9", position: 'relative', marginLeft: 10 }}
                    activeLabelStyle={{ color: "#c9c9c9", position: 'relative', marginLeft: 10 }}
                    onChangeItem={(item) => {
                        this.setState({
                            category: item.label
                        });
                    }}
                    dropDownMaxHeight={240}
                />

                <Text style={styles.heading}>Select a Location</Text>
                <DropDownPicker
                    zIndex={4000}
                    items={[
                        { label: 'Johor' },
                        { label: 'Kedah' },
                        { label: 'Kelantan' },
                        { label: 'KL/Selangor' },
                        { label: 'Melaka' },
                        { label: 'Negeri Sembilan' },
                        { label: 'Pahang' },
                        { label: 'Penang' },
                        { label: 'Perak' },
                        { label: 'Perlis' },
                        { label: 'Sabah' },
                        { label: 'Sarawak' },
                        { label: 'Terengganu' }
                    ]}
                    defaultNull={this.state.location === ''}
                    placeholder="Select a state"
                    containerStyle={styles.dropdown}
                    style={{ backgroundColor: 'white', borderTopLeftRadius: 25, borderTopRightRadius: 25, borderBottomLeftRadius: 25, borderBottomRightRadius: 25 }}
                    dropDownStyle={{ backgroundColor: 'white', borderBottomLeftRadius: 25, borderBottomRightRadius: 25 }}
                    placeholderStyle={{ color: "#c9c9c9", position: 'absolute', left: 0 }}
                    labelStyle={{ color: "#c9c9c9", position: 'relative', marginLeft: 10 }}
                    activeLabelStyle={{ color: "#c9c9c9", position: 'relative', marginLeft: 10 }}
                    onChangeItem={(item) => {
                        this.setState({
                            location: item.label
                        });
                    }}
                    dropDownMaxHeight={240}
                />

                <Text style={styles.heading}>Offer Description</Text>
                <TextInput
                    style={styles.description}
                    placeholder="Describe your offer - what does it look like? What are its dimensions? How much is available? Can the recipient take a partial amount or does it have to be all?"
                    onChangeText={description => this.setState({ description })}
                    multiline={true}
                    maxLength={300}
                    clearButtonMode='while-editing'
                    value={this.state.description}
                />
                <View style={{ flexDirection: 'row' }}>
                    <Text style={styles.heading}>Offer Expiry Date (optional)</Text>
                    <TouchableOpacity style={{ position: 'absolute', right: 0 }} onPress={this.showPicker}><Text style={{ color: "#CFC8EF" }}>Choose Date</Text></TouchableOpacity>
                </View>

                <Text style={{ marginLeft: 10, color: "#2C2061" }}>{this.state.expiry}</Text>

                <DateTimePickerModal
                    isVisible={this.state.isVisible}
                    mode={"date"}
                    onConfirm={this.handlePicker}
                    onCancel={this.hidePicker}
                    datePickerModeAndroid={'spinner'}
                />
                <TouchableHighlight
                    style={styles.button}
                    underlayColor="black"
                    onPress={this.handleSubmit}
                >
                    <Text style={styles.buttonText}>CONFIRM</Text>
                </TouchableHighlight>
                <View style={{ height: 50 }}></View>
            </KeyboardAwareScrollView>
        );
    }
}
export default Edit;

