		ajustWidth: function(){
			var maxw = $(window).width();
			var w1 = maxw * 0.50,
				w2 = maxw * 0.05,
				w3 = maxw * 0.33,
				w4 = maxw * 0.10;
			$('.td1').css('width', w1);
			$('.td2').css('width', w2);
			$('.td3').css('width', w3);
			$('.td4').css('width', w4);
