				obj = page.datas[i];
				if(obj.version == v){
					return obj;
				}
			}
			return null;
		},

		bindEvent: function(){
			$('#project').on('change', function(){
				var $this = $(this),
					pv = $this.val();
				if(pv == 'add'){
					$this.val('');
					$this.trigger('chosen:updated');

					// 创建iframe弹出框
					window['$addDialog'] = new $.zui.ModalTrigger({
						name: 'addpFrame',
						title: '添加SVN项目信息',
						backdrop: 'static',
						moveable: true,
						waittime: consts.PAGE_LOAD_TIME,
						width: 650,
						height: 350,
						iframe: './svn_add.html'
					});
					// 显示弹出框
					$addDialog.show();
				} else if(pv){
					page.load(pv);
				}
			});

			$('.btn-load').on('click', function(){
				page.loadProjects();
			});

			$('.version-box').on('click', '.trow', function(){
				var $tr = $(this),
					ver = $tr.data('id');
				var obj = page.getVersionData(ver);
				$('.version-box .trow').removeClass('active');
				$tr.addClass('active');
				if(obj){
					$('.desc-view').val(obj.desc);
					page.renderTable2(obj.files, ver);
				} else {
					$('.desc-view').val('');
				}
			});

			$(window).on('resize', function (e) {
				page.ajustWidth();
			});

			$('.files-box').on('click', '.file-item', function(){
				var $this = $(this),
					path = $this.data('id'),
					mode = $this.data('mode'),
					ver = $this.data('ver');
				var p = "s=" + page.svnsrv + "&p=" + path;
				if(mode != 'D'){
					p += "&v=" + ver;
				} else {
					alert("文件已被删除");
					return;
				}

				if(top['SYSTEM']){
					top['SYSTEM']['openWindow']({
						title: "文件内容预览 - " + path,
						types: 'exe',
						url: consts.WEB_BASE + 'apps/svn/svn_editor.html?' + p,
						width: 1100,
						height: 700,
						needMax: false,
						needMin: false,
						desktopIconId: 'cus-' + new Date().getTime(),
						icon: consts.WEB_BASE + 'content/images/icons/svn.png'
					});
				} else {
					// 创建iframe弹出框
					window['$svnDialog'] = new $.zui.ModalTrigger({
						name: 'multiFrame',
						title: "文件内容预览 - " + path,
						backdrop: 'static',
						moveable: true,
						waittime: consts.PAGE_LOAD_TIME,
						width: 1100,
						height: 700,
						iframe: './svn_editor.html?' + p
					});
					// 显示弹出框
					$svnDialog.show();
				}

			});

			var timer = 0, oldname = '';
			$('#filename').on('keyup', function(){
				var $this = $(this),
					name = $this.val(),
					$tr = $('.version-box .trow.active');
				if($tr.length && name != oldname){
					oldname = name;
					var ver = $tr.data('id');
					if(timer){
						clearTimeout(timer);
					}
					timer = setTimeout(function(){
						var obj = page.getVersionData(ver);
						if(obj){
							page.renderTable2(obj.files, ver);
						}
					}, 300);
				}
			});

		}

	};
	var page = new PageScript();
	window['loadProject'] = page.loadProjects;
	page.init();
});

