import React, { useContext, useState } from 'react';
import Typography from '@material-ui/core/Typography';
import { getDocument } from 'lbd-server';
import AppContext from "@context";


export default function Damagedata(props) {

    const { context, setContext } = useContext(AppContext);
    const info = props.allInfo[props.currentURI]

    //don't display
    if (info === undefined || props.checked === false) {
        return (
            <div></div>
        )
    }


    ///////////////////////////////////////////////////////////////////////////////////////what to display
    if ((props.checked === true)) {

        //////////////////////////////////////////////////////////////GUID

        const clickGuid = () => {
            const selection = [{guid: info.objectGuid[0]}]
            setContext({...context, selection})
            console.log(context)
          };

        //////////////////////////////////////////////////////////////currently occuring
        const currentlyOccuring = () => {
            if (info.stateType === true) {
                return (
                    <Typography className='damageInfoDetail'>
                        Currently occuring
                    </Typography>
                )
            } else {
                return (
                    <Typography className='damageInfoDetail'>
                        Resolved
                    </Typography>
                )
            }
        }

        //////////////////////////////////////////////////////////////damage type
        const damageTypes = info.damageType.map((element, i) => {
            return (
                <div>
                    <Typography key={i} className='damageInfoDetail'>
                        <li> {element}</li>
                    </Typography>
                </div>
            )
        })

        //////////////////////////////////////////////////////////////task
        const orderTask = () => {
            if (info.task === true && info.taskType === undefined) {
                return (
                    <div>
                        <Typography className='damageInfo'>
                            Assigned repair tasks:
                        </Typography>
                        <Typography className='damageInfoDetail'>
                            undefined task ordered
                    </Typography>
                    </div>
                )
            }
            if (info.task === true && info.taskType !== undefined) {
                return (
                    <Typography className='damageInfo'>
                        Assigned repair tasks:
                    </Typography>
                )
            } else {
                return
            }
        }

        const taskTypes = info.taskType.map((element, i) => {
            return (
                <div>
                    <Typography key={i} className='damageInfoDetail'>
                        <li> {element}</li>
                    </Typography>
                </div>
            )
        })

        const taskComment = () => {
            if (info.taskComment !== undefined) {
                return (
                    <Typography className='damageInfoDetail' style={{ paddingTop: '20px' }}>
                        Comment: {info.taskComment}
                    </Typography>
                )
            } else {
                return
            }
        }


        //////////////////////////////////////////////////////////////Comment

        const comment = () => {
            if (info.comment !== undefined) {
                return (
                    <div>
                        <Typography className='damageInfo'>
                            Comment:
                        </Typography>
                        <Typography className='damageInfoDetail'>
                            {info.comment}
                        </Typography>
                    </div>
                )
            } else {
                return
            }
        }

        //////////////////////////////////////////////////////////////Document

        const documentSelection = () => {
            if (info.doc.join() !== '') {
                const damage = info.doc.map((element,i)=>{


                    const displayImage = ()=>{
                        var name = element.name.replaceAll('.', '.$')
                        var arrayName = name.split("$")
                        var label = arrayName[arrayName.length - 1]

                        if(label === 'jpg' || label === 'JPG' || label === 'JPEG'|| label === 'jpeg' || label === 'TIFF' || label === 'tif' || label === 'tiff' || label === 'png' || label === 'PNG'){
                            return <img src={element.uri.replace("https://lbdserver.org/", "http://localhost:5000/")} alt={element.name} width="80%" ></img>
                        } else{
                            return
                        }
                    } 


                    return (
                        <Typography key={i} className='damageInfoDetail'>
                            <li className = "link" onClick ={()=>downloadDoc(element.uri)}> {element.name} </li>
                            {displayImage()}
                         </Typography>
                    )
                })

                return (
                    <div>
                        <Typography className='damageInfo'>
                            Document(s):
                        </Typography>
                        {damage}
                    </div>
                )
            } else {
                return
            }
        }



        function downloadDoc(uri) {
            window.open(uri.replace("https://lbdserver.org/", "http://localhost:5000/"));
        }  



        /////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////RETURN
        return (
            <div>
                <Typography className='damageInfo'>
                    Object GUID:
                </Typography>
                <Typography className='damageInfoDetail'>
                    {/* <div onClick={()=>console.log('test')}>{info.objectGuid}</div> */}
                    <div className = "link" onClick={()=>clickGuid()}>{info.objectGuid}</div>
                </Typography>

                <Typography className='damageInfo'>
                    Damage status:
                </Typography>
                {currentlyOccuring()}

                <Typography className='damageInfo'>
                    Date of corresponding damage state:
                </Typography>
                <Typography className='damageInfoDetail'>
                    {info.timeOfGeneration}
                </Typography>


                <Typography className='damageInfo'>
                    Damage type:
                </Typography>
                {damageTypes}


                {orderTask()}
                {taskTypes}
                {taskComment()}

                {comment()}

                {documentSelection()}


            </div>
        )


    } else { return (<div></div>) }

}

