  routes: [
    {
      path: '/',
      name: 'navMenu',
      redirect: '/home',
      component: NavMenu,
      children: [
        { path: '/home', component: Home },
        { path: '/autoControl', component: AutoControl },
        { path: '/setting', component: Setting },
