router.beforeEach((to, from, next) => {
  const user = sessionStorage.getItem('user');
  if (to.path === '/login') {
    if (user) {
      next({ path: '/' });
    } else {
      next();
    }
  } else if (!user) {
    next({ path: '/login' });
  } else {
    next();
  }
});

export default router;

