function replaceAll(find, replace, str) {
  return str.replace(new RegExp(find, 'g'), replace);
}

function ClusterIcon(cluster, styles) 
{
  cluster.getMarkerClusterer().extend(ClusterIcon, google.maps.OverlayView);

  this.cluster_ = cluster;
  this.className_ = cluster.getMarkerClusterer().getClusterClass();
  this.styles_ = styles;
  this.center_ = null;
  this.div_ = null;
  this.sums_ = null;
  this.visible_ = false;
  this.DDivsVisible = false;

  this.damage_divs_ = [];
  this.setMap(cluster.getMap()); // Note: this causes onAdd to be called


  this.clusterClickListener = function() 
  {
	var clusters = window.reconCluster.clusters_;//this.clusterIcon_.cluster_.markerClusterer_.clusters_;
	var i = 0;

    for (i = 0; i < clusters.length; i++) 
		clusters[i].clusterIcon_.hideDDivs();

	clusters = window.citizenCluster.clusters_;

    for (i = 0; i < clusters.length; i++) 
		clusters[i].clusterIcon_.hideDDivs();

	if(window.openTooltip)
	{
		if(window.openTooltip.ddiv_)
		{
			window.openTooltip.ddiv_.infoOpen = false;
			$(window.openTooltip.ddiv_.closeBox).hide();
		}

		if(window.openTooltip.closeBox)
			$(window.openTooltip.closeBox).hide();

		$(window.openTooltip).slideUp();
	}

  	this.clusterIcon_.showDDivs();
  };

}

