      mongoose.deleteModel(/Test/);
    });

    it('filter', function() {
      const Model = mongoose.model('Test', Schema({ arr: [String] }));
      const doc = new Model({ arr: ['foo', 'bar', 'baz'] });

      const arr = doc.arr.filter(str => str.startsWith('b'));
      assert.deepEqual(arr, ['bar', 'baz']);
      assert.ok(!arr.isMongooseArray);
    });

    it('flat', function() {
      if (Array.prototype.flat == null) {
        return this.skip();
      }

      const Model = mongoose.model('Test', Schema({ arr: [[String]] }));
      const doc = new Model({ arr: [['foo']] });

      const arr = doc.arr.flat();
      assert.deepEqual(arr, ['foo']);
      assert.ok(!arr.isMongooseArray);
    });

    it('flatMap', function() {
      if (Array.prototype.flatMap == null) {
        return this.skip();
      }

      const Model = mongoose.model('Test', Schema({ arr: [Number] }));
      const doc = new Model({ arr: [1, 3, 5, 7] });

      const arr = doc.arr.flatMap(v => [v, v + 1]);
      assert.deepEqual(arr, [1, 2, 3, 4, 5, 6, 7, 8]);
      assert.ok(!arr.isMongooseArray);
    });

    it('map', function() {
      const Model = mongoose.model('Test', Schema({ arr: [Number] }));
      const doc = new Model({ arr: [2, 4, 6, 8] });

      const arr = doc.arr.map(v => v / 2);
      assert.deepEqual(arr, [1, 2, 3, 4]);
      assert.ok(!arr.isMongooseArray);
    });

    it('slice', function() {
      const Model = mongoose.model('Test', Schema({ arr: [Number] }));
      const doc = new Model({ arr: [2, 4, 6, 8] });

      const arr = doc.arr.slice(1, 3);
      assert.deepEqual(arr, [4, 6]);
      assert.ok(!arr.isMongooseArray);
    });
  });
});

#!/bin/env node

const spawn = require('child_process').spawn;
const PackageConfig = require('../package.json');
const dir = require('path').resolve(__dirname, '../');

function build() {
    return new Promise(function(resolve, reject) {
        const build = spawn('node_modules/.bin/cross-env', ['NODE_ENV=production', 'node_modules/.bin/webpack', '--progress'], {
            cwd: dir,
            stdio: 'inherit'
        });

        build.on('close', (code) => {
            console.log(`child process exited with code ${code}`);
            if (code === 0)
                resolve();
            else {
                reject();
            }
        });
    });
}

function pack() {
    return new Promise(function(resolve, reject) {
        const tar = spawn('tar', ['-C', 'build', '-cvaf', 'lightdm-webkit2-material2-'+PackageConfig.version+'.tar.gz', '.'], {
            cwd: dir,
            stdio: 'inherit'
        });

        tar.on('close', (code) => {
            console.log(`child process exited with code ${code}`);
            if (code === 0)
                resolve();
            else {
                reject();
            }
        });
    });
}

build().then(() => new Promise((resolve, reject) => {
    if (process.argv.indexOf('-p') > 0) {
        pack().then(resolve, reject);
    } else {
        resolve();
    }
})).then(function() {
    console.log('Done!');
}).catch((err) => {
    console.log('ERROR:', err);
});

/**
 * 关于登录接口
 * setLoginIn:用户登录
 *setLoginOut:用户退出
 */
import request from '../utils/request';

export async function setLoginIn(params) {
  var { username, password, imgcode} = params;
  var paramsStr = `username=${username}&password=${password}&imgcode=${imgcode}`;
  return request('/system/user/login.htm',{
    method: 'POST',
    body: paramsStr,
  });
}

export async function setLoginOut() {
  return request('/system/user/logout.htm',{
    method: 'POST',
    body: {},
  });
}

