			textToDomToParent(`<${COMPONENT_NAME}></${COMPONENT_NAME}>`)
		);
		await waitNextTask();
		g.addEventListener('selected-items-changed', () => fires++);
		g.columns = getColumns();
		g.items = getItems(3);

		await waitNextTask();
		g.selectItem(g.items[0]);
		g.selectItem(g.items[1], true);
