test('useModel', (done) => {
  const counter = ({ get, set }) => ({
    count: 0,
    open: false,
    add() {
      const { count } = get();
      set({ count: count + 1 });
    },
    async addAsync() {
      await new Promise((resolve) => setTimeout(resolve, 0));
      const { add } = get();
      add();
    },
    toggle() {
      set((state) => ({ open: !state.open }));
    },
  });

  const error = ({ get, set }) => ({
    errPayload() {
      set([]);
    },
    errOutModel() {
      const { add } = get(counter);
      add();
      const { notExist } = get(1);
    },
  });

  const Counter = () => {
    const { count, add, addAsync } = useModel(counter);
    const { open, toggle } = useModel(counter);
    const { errPayload, errOutModel } = useModel(error);

    return (
      <>
        <p>{count}</p>
        <p>{open}</p>
        <button id="add" onClick={add} />
        <button id="addAsync" onClick={addAsync} data-loading={addAsync.loading} />
        <button id="toggle" onClick={toggle} />
        <button id="errPayload" onClick={errPayload} />
        <button id="errOutModel" onClick={errOutModel} />
      </>
    );
  };

  const wrapper = mount(<Counter />);
  const click = (el) => wrapper.find(el).simulate('click');
  const threw = (fn) => expect(fn).toThrow();

  click('#add');
  click('#addAsync');
  click('#addAsync');
  click('#toggle');

  threw(() => useModel());
  threw(() => click('#errPayload'));
  threw(() => click('#errOutModel'));

  setTimeout(() => {
    wrapper.unmount();
    done();
  }, 0);
});

var SBOLDocument = require('sboljs')

var getSBOL = require('../getSBOL')

var sbolRdfToXml = require('../sbolRdfToXml')

var sparql = require('../sparql')

var config = require('config')

var federate = require('../federate')
var collateSBOL = require('../collateSBOL')

var loadTemplate = require('../loadTemplate')

const getRdfSerializeAttribs = require('../getRdfSerializeAttribs')

function ComponentInteractionsEndpoint(type) {

    return federate(endpoint, collateSBOL)

    function endpoint(req, callback) {

        console.log('endpoint: ComponentInteractionsEndpoint')

        var uri

        if(req.params.prefix) {

            var prefixes = config.get('prefixes')

            var baseUri = prefixes[req.params.prefix]

            if(!baseUri) {
                return callback(new Error('unknown prefix: ' + req.params.prefix))
            }

            uri = baseUri + req.params.uri

        } else {

            uri = req.params.uri

        }

        var sbol = new SBOLDocument()

        var query = loadTemplate('./sparql/ComponentInteractions.sparql', {           
            uri: uri
        });

        console.log(query)

        sparql.queryJson(query, req.params.store, function(err, type, results) {

            if(err)
                return callback(err);

            console.log(results)

            var interactionURIs = []

            results.forEach((result) => {

                interactionURIs.push(result.module)
                interactionURIs.push(result.interaction)

            })

            getSBOL(sbol, req.params.store, interactionURIs, (err, sbol) => {

                if(err)
                    return callback(err)

                callback(null, 200, {
                    mimeType: 'application/rdf+xml',
                    body: sbol.serializeXML(getRdfSerializeAttribs())
                })
            })
        })

    }
}

module.exports = ComponentInteractionsEndpoint

