                $scope.$parent.max_health   = response.result.max_health;
                $scope.showRedeem           = response.result.redeem_time;
            }
        });

        fetcher.getLeaderboard(function (response) {
            $scope.leaderboard = response.result;
        });
    };

    init();
}]);

