// @flow
import type { HullContext, HullUISelectResponse } from "hull";

const prospect = async (ctx: HullContext): HullUISelectResponse => {
  const { mappingToOptions } = ctx.helpers;
  return {
    status: 200,
    data: mappingToOptions({
      type: "prospect",
      direction: "incoming",
      label: "Clearbit Prospect"
    })
  };
};
export default prospect;

import request from '@/utils/request'
import { Message } from 'element-ui'

function getSamples(params) {
  return request({
    url: '/products/samples',
    method: 'GET',
    params
  })
}

function setSample(_id) {
  return request({
    url: '/products/do-return-sample',
    data: {
      _id
    },
    method: 'PUT'
  })
}

const state = {
  samplesTable: [],
  tableLoading: false,
  queryParams: {
    search_input: 'name',
    search_text: '',
    currentPage: 1,
    perPage: 120,
    shop: '',
    return_status: 2
  },
  total: 0
}
const mutations = {
  SET_QUERY: (state, data) => {
    state.queryParams[data.key] = data.value
  },
  SET_TABLE_LOADER: (state, status) => {
    state.tableLoading = status
  },
  SET_TABLE_DATA: (state, data) => {
    state.total = data.length
    state.samplesTable = data
    state.samplesTable.forEach(elem => {
      const totalArea = elem.products.reduce((acc, val) => acc + val.packTotalArea, 0)
      const totalNumber = elem.products.reduce((acc, val) => acc + val.item_num, 0)
      elem.totalArea = totalArea
      elem.totalNumber = totalNumber
    })
  }
}
const actions = {
  GET_SAMPLES: ({ commit, state }) => {
    return new Promise((resolve, reject) => {
      commit('SET_TABLE_LOADER', true)
      getSamples(state.queryParams).then(res => {
        commit('SET_TABLE_DATA', res.data)
        commit('SET_TABLE_LOADER', false)
        resolve()
      }).catch(err => {
        commit('SET_TABLE_LOADER', false)
        reject(err)
      })
    })
  },
  DO_RETURN: ({ commit }, data) => {
    return new Promise((resolve, reject) => {
      commit('SET_TABLE_LOADER', true)
      setSample(data).then(res => {
        Message({
          message: res.data.message,
          duration: 2500,
          type: 'success'
        })
        resolve()
      }).catch(err => {
        Message({
          message: err.response.data,
          duration: 2500,
          type: 'success'
        })
        reject(err)
      })
    })
  }
}

export default {
  namespaced: true,
  state,
  mutations,
  actions
}

const express = require("express");
const { ApolloServer } = require("apollo-server-express");
const path = require("path");
const db = require("./config/connection");
const { typeDefs, resolvers } = require("./schemas");
const authMiddleWare = require("./utils/auth");
require("dotenv").config();

const PORT = process.env.PORT || 3001;

async function startApolloServer(typeDefs, resolvers) {
  const server = new ApolloServer({
    typeDefs,
    resolvers,

    context: authMiddleWare,
  });

  // const server = new ApolloServer({
  //   typeDefs,
  //   resolvers,
  //   context: authMiddleWare,
  // });
  await server.start();
  const app = express();
  app.use(
    express.urlencoded({
      extended: false,
    })
  );
  app.use(express.json());
  server.applyMiddleware({
    app,
    path: "/graphql",
  });
  // ... other app.use middleware
  app.use(express.static(path.join(__dirname, "client", "build")));
  app.get("*", (req, res) => {
    res.sendFile(path.join(__dirname, "client", "build", "index.html"));
  });
  await new Promise((resolve) => app.listen({ port: PORT }, resolve));
  console.log(`API server running on port ${PORT}!`);
  console.log(
    `🚀 Server ready at http://localhost:${PORT}${server.graphqlPath}`
  );
}

db.once("open", () => {
  startApolloServer(typeDefs, resolvers);
});

