export default function smoothScroll(target) {
  var scrollContainer = target
  do {
    //find scroll container
    scrollContainer = scrollContainer.parentNode
    if (!scrollContainer) return
    scrollContainer.scrollTop += 1
  } while (scrollContainer.scrollTop == 0)

  var targetY = 0
  do {
    //find the top of target relatively to the container
    if (target == scrollContainer) break
    targetY += target.offsetTop
  } while ((target = target.offsetParent))

  scroll = function(c, a, b, i) {
    i++
    if (i > 30) return
    c.scrollTop = a + (b - a) / 30 * i
    setTimeout(function() {
      scroll(c, a, b, i)
    }, 20)
  }
  // start scrolling
  scroll(scrollContainer, scrollContainer.scrollTop, targetY, 0)
}

import Route from '@ember/routing/route';
import moment from 'moment';
import { set } from '@ember/object';
import { inject as service } from '@ember/service';
import ENV from 'open-event-frontend/config/environment';

export default Route.extend({
  headData: service(),
  async model() {
    const eventDetails = this.modelFor('public');
    return {
      event   : eventDetails,
      tickets : await eventDetails.query('tickets', {
        reload: true,

        filter: [
          {
            and: [
              {
                name : 'sales-starts-at',
                op   : 'le',
                val  : moment().toISOString()
              },
              {
                name : 'sales-ends-at',
                op   : 'ge',
                val  : moment().toISOString()
              }
            ]
          }
        ]
      }),
      speakers: await eventDetails.query('speakers', {
        filter: [
          {
            or: [
              {
                name : 'sessions',
                op   : 'any',
                val  : {
                  name : 'state',
                  op   : 'eq',
                  val  : 'confirmed'
                }
              },
              {
                name : 'sessions',
                op   : 'any',
                val  : {
                  name : 'state',
                  op   : 'eq',
                  val  : 'accepted'
                }
              }
            ]
          }
        ],
        'page[size]': 0
      }),

      sponsors : await eventDetails.get('sponsors'),
      tax      : await eventDetails.get('tax'),
      order    : this.store.createRecord('order', {
        event   : eventDetails,
        user    : this.get('authManager.currentUser'),
        tickets : []
      }),

      attendees: [],

      mapConfig: ENV.APP.mapConfig
    };
  },
  afterModel(model) {
    set(this, 'headData.description', model.event.description);
  },
  resetController(controller) {
    this._super(...arguments);
    const model = controller.get('model.order');
    if (!model.id) {
      model.unloadRecord();
    }
  }
});

