/**
 * Params: array, filterValue
 * Response: array element
 * Description: Returns a filtered value from an array
 */
function getName(arr, filterValue) {
  for (let k = 0; k < arr.length; k++) {
    if (arr[k] === filterValue) {
      return arr[k];
    }
  }
}

