          S: subAttr.Value
        },
      },
      ExpressionAttributeNames: {
        '#Username': 'Username', 
        '#Avatar': 'Avatar', 
        '#BgColor': 'BgColor', 
        '#Name': 'Name',
        '#Channel': 'Channel'
       }, 
       ExpressionAttributeValues: {
