export function isSshRepositoryUrl(url) {
    if (!url || url.trim() === '') {
        return false;
    }

    if (/^ssh:\/\/.*/.test(url)) {
        return true;
    }

    if (/^[^@:]+@.*/.test(url)) {
        return true;
    }

    return false;
}

