            values: ["arweave-avatar"]
          }
        ],
        owners: ["${walletAddress}"]
      ) {
        edges {
          node {
            id
          }
        }
      }
    }`})
  let edges = results.data.data.transactions.edges;
  let txIds = edges.map(e => e.node.id);
