                        fmt.end();
                        callback();
                    } catch (ee) { callback(ee); }
                });
                stream.on("error", done);
                file.contents = file.contents.pipe(stream);
                done(null, file);
            } else done(new PluginError("gulp-json-fmt", "Invalid input type"));
        } catch (e) {
            done(new PluginError("gulp-json-fmt", e));
        }
