    // we're asked to draw line to itself
    return []
  }

  if (rx === 0 || ry === 0) {
    // one of the radii is zero
    return []
  }

  // Compensate out-of-range radii
  //
  rx = Math.abs(rx)
  ry = Math.abs(ry)

  const lambda = (x1p * x1p) / (rx * rx) + (y1p * y1p) / (ry * ry)
  if (lambda > 1) {
    rx *= Math.sqrt(lambda)
    ry *= Math.sqrt(lambda)
