import gql from 'graphql-tag';
import graphqlClient from 'modules/shared/graphql/graphqlClient';

export default class IamService {
  static async enable(ids) {
    return this._changeStatus(ids, false);
  }

  static async disable(ids) {
    return this._changeStatus(ids, true);
  }

  static async _changeStatus(ids, disabled) {
    const response = await graphqlClient.mutate({
      mutation: gql`
        mutation IAM_CHANGE_STATUS(
          $ids: [String!]!
          $disabled: Boolean
        ) {
          iamChangeStatus(ids: $ids, disabled: $disabled)
        }
      `,

      variables: {
        ids,
        disabled: !!disabled,
      },
    });

    return response.data.iamChangeStatus;
  }

  static async edit(data) {
    const response = await graphqlClient.mutate({
      mutation: gql`
        mutation IAM_EDIT($data: IamEditInput!) {
          iamEdit(data: $data)
        }
      `,

      variables: {
        data,
      },
    });

    return response.data.iamEdit;
  }

  static async remove(emails, roles, all = false) {
    const response = await graphqlClient.mutate({
      mutation: gql`
        mutation IAM_REMOVE(
          $emails: [String!]!
          $roles: [String!]!
          $all: Boolean
        ) {
          iamRemove(
            emails: $emails
            roles: $roles
            all: $all
          )
        }
      `,

      variables: {
        emails,
        roles,
        all,
      },
    });

    return response.data.iamRemove;
  }

  static async create(data) {
    const response = await graphqlClient.mutate({
      mutation: gql`
        mutation IAM_CREATE($data: IamCreateInput!) {
          iamCreate(data: $data)
        }
      `,

      variables: {
        data,
      },
    });

    return response.data.iamCreate;
  }

  static async import(values, importHash) {
    const response = await graphqlClient.mutate({
      mutation: gql`
        mutation IAM_IMPORT(
          $data: IamImportInput!
          $importHash: String!
        ) {
          iamImport(data: $data, importHash: $importHash)
        }
      `,

      variables: {
        data: {
          ...values,
        },
        importHash,
      },
    });

    return response.data.iamImport;
  }

  static async find(id) {
    const response = await graphqlClient.query({
      query: gql`
        query IAM_FIND($id: String!) {
          iamFind(id: $id) {
            id
            fullName
            firstName
            lastName
            authenticationUid
            phoneNumber
            email
            roles
            createdAt
            updatedAt
            disabled
            avatars {
              id
              name
              sizeInBytes
              publicUrl
              privateUrl
            }
            patient {
              id
              name
            }
          }
        }
      `,

      variables: {
        id,
      },
    });

    return response.data.iamFind;
  }

  static async fetchUsers(filter, orderBy, limit, offset) {
    const response = await graphqlClient.query({
      query: gql`
        query IAM_LIST_USERS(
          $filter: IamListUsersFilterInput
          $orderBy: UserWithRolesOrderByEnum
          $limit: Int
          $offset: Int
        ) {
          iamListUsers(
            filter: $filter
            orderBy: $orderBy
            limit: $limit
            offset: $offset
          ) {
            count
            rows {
              id
              fullName
              email
              phoneNumber
              avatars {
                id
                name
                sizeInBytes
                publicUrl
                privateUrl
              }
              disabled
              roles
              createdAt
            }
          }
        }
      `,

      variables: {
        filter,
        orderBy,
        limit,
        offset,
      },
    });

    return response.data.iamListUsers;
  }

  static async fetchRoles(filter, orderBy, limit, offset) {
    const response = await graphqlClient.query({
      query: gql`
        query IAM_LIST_ROLES(
          $filter: IamListRolesFilterInput
          $orderBy: RoleWithUsersOrderByEnum
        ) {
          iamListRoles(filter: $filter, orderBy: $orderBy) {
            role
            users {
              id
              fullName
              email
              disabled
              createdAt
            }
          }
        }
      `,

      variables: {
        filter,
        orderBy,
      },
    });

    const rows = response.data.iamListRoles;

    return {
      rows,
      count: rows.length,
    };
  }

  static async fetchUserAutocomplete(query, limit) {
    const response = await graphqlClient.query({
      query: gql`
        query IAM_USER_AUTOCOMPLETE(
          $query: String
          $limit: Int
        ) {
          iamUserAutocomplete(
            query: $query
            limit: $limit
          ) {
            id
            label
          }
        }
      `,

      variables: {
        query,
        limit,
      },
    });

    return response.data.iamUserAutocomplete;
  }
}

const fs = require('fs')
const MBTiles = require('@mapbox/mbtiles')
const express = require('express')
const spdy = require('spdy')
const cors = require('cors')
const config = require('config')

const app = express()
app.use(cors())
let mbtiles = {}

/* get the port: override by command line parameter */
let port = config.get('port')
if (process.argv.length === 3) {
  port = parseInt(process.argv[2])
}

const scanFiles = () => {
  fs.readdir('mbtiles', (err, files) => {
    if (err) throw err
    for (let file of files) {
      if (file.endsWith('.mbtiles')) {
        const t = file.replace('.mbtiles', '')
        if (mbtiles[t]) continue
        // console.log(`opening ${t}`)
        new MBTiles(`mbtiles/${file}?mode=ro`, (err, mbt) => {
          if (err) throw err
          mbtiles[t] = mbt
        })
      }
    }
  })
}
scanFiles()

app.get('/zxy/:t/:z/:x/:y', (req, res, next) => {
  const [z, x, y] = [req.params.z, req.params.x, req.params.y].map(v => Number(v))
  const t = req.params.t
  getTile(t, z, x, y).then(tile => {
    if (tile) {
      res.set('Content-Encoding', 'gzip')
      res.send(tile)
    } else {
      res.status(404).send(`${t}/${z}/${x}/${y} does not exist.`)
    }
  }).catch(reason => {
    throw reason
  })
})

app.get('/module/:z/:x/:y', (req, res, next) => {
  const [z, x, y] = [req.params.z, req.params.x, req.params.y].map(v => Number(v))
  const Z = 5
  const X = x >> (z - Z)
  const Y = y >> (z - Z)
  const t = `${Z}-${X}-${Y}`
  getTile(t, z, x, y).then(tile => {
    if (tile) {
      res.set('Content-Encoding', 'gzip')
      res.send(tile)
    } else {
      res.status(404).send(`${t}/${z}/${x}/${y} does not exist.`)
    }
  }).catch(reason => {
    throw reason
  })
})

app.get('/module6/:z/:x/:y', (req, res, next) => {
  const [z, x, y] = [req.params.z, req.params.x, req.params.y].map(v => Number(v))
  const Z = 6 
  const X = x >> (z - Z)
  const Y = y >> (z - Z)
  const t = `${Z}-${X}-${Y}`
  getTile(t, z, x, y).then(tile => {
    if (tile) {
      res.set('Content-Encoding', 'gzip')
      res.send(tile)
    } else {
      res.status(404).send(`${t}/${z}/${x}/${y} does not exist.`)
    }
  }).catch(reason => {
    throw reason
  })
})

const getTile = (t, z, x, y) => {
  if (!mbtiles[t]) scanFiles()
  return new Promise((resolve, reject) => {
    if (!mbtiles[t]) resolve(false)
    mbtiles[t].getTile(z, x, y, (err, data, headers) => {
      if (err) {
        resolve(false)
      } else {
        resolve(data)
      }
    })
  })
}
app.use(express.static('htdocs'))

/* be sure to change style.json if you want to use http
app.listen(port, () => {})
*/

spdy.createServer({
  key: fs.readFileSync('privkey.pem'),
  cert: fs.readFileSync('fullchain.pem'),
  ca: fs.readFileSync('chain.pem')
  // key: fs.readFileSync('private.key'), 
  // cert: fs.readFileSync('server.crt'),
  // passphrase: 'tile-block'
}, app).listen(port, () => { })

const mongoose = require('mongoose')

const userSchema = new mongoose.Schema({
  email: {
    type: String,
    required: true,
    unique: true
  },
  hashedPassword: {
    type: String,
    required: true
  },
  token: String
}, {
  timestamps: true,
  toObject: {
    // remove `hashedPassword` field when we call `.toObject`
    transform: (_doc, user) => {
      delete user.hashedPassword
      return user
    }
  }
})

module.exports = mongoose.model('User', userSchema)

